(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-slim-scheduler-a-runtime-aware-rl-an-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-1\">一 · 现场：一条被长尾样本拖住的在线链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-2\">二 · 旧方案的结构性盲点：调度器看不见运行时</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-3\">三 · 解耦的隐性账单：KV 复用与前缀共享跨不过阶段边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-4\">四 · 为什么非改不可：RL 后训练把矛盾放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-5\">五 · 一个具体例子：同一批样本在两种调度下的路径差异</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-6\">六 · 工程判断：改的是调度入口，不是加一张卡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-7\">七 · 请求长度分布是调度器的第一手输入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-8\">八 · 并发与批大小：回压是双向约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-9\">九 · SLO 与长尾：尾延迟的分母问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-10\">十 · 验证器请求流：被忽略的负载维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-11\">十一 · 负载与方案的双向塑造：可核查的测量清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-12\">十二 · 负载形态与调度边界的相互塑形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-13\">十三 · 从调度决策到 kernel 选择：运行时状态如何落到算子层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-14\">十四 · 数据类型谱系：FP16/BF16 到 FP8 再到 NVFP4 的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-15\">十五 · tcgen05、TMEM 与 2-SM MMA：累加器住在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-16\">十六 · 累加精度与误差在调度链路中的传播</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-17\">十七 · 第五代 Tensor Core 的吞吐账与调度器的可见性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-18\">十八 · 工程判断：精度与调度的耦合点在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-19\">十九 · 精度档位缺失下的调度边界：KV预算、长尾分组与验证器流的耦合代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-20\">二十 · 显存账本的三个账户：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-21\">二十一 · 分页与压缩：把 KV 从连续块变成可调度单元</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-22\">二十二 · 复用与卸载：跨阶段共享与容量换带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-23\">二十三 · 带宽瓶颈在哪：HBM3e 的读放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-24\">二十四 · 可复算的显存预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-25\">二十五 · 预算与调度的耦合判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-26\">二十六 · 运行时感知调度的显存边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-27\">二十七 · 连续批处理的运行时判据：批构成决定复用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-28\">二十八 · Chunked prefill 与解码的混批：把长预填切碎塞进解码间隙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-29\">二十九 · 优先级与抢占：长尾样本单独成组与回压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-30\">三十 · 分离式预填/解码在统一调度入口下的形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-31\">三十一 · 尾延迟的压缩路径：从批内方差到队列深度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-32\">三十二 · 时延与吞吐的取舍落在哪个旋钮上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-33\">三十三 · 切分维度与通信原语的对应关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-34\">三十四 · NVLink 5、NVSwitch 与域边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-35\">三十五 · All-to-All 与 All-Reduce 的瓶颈判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-36\">三十六 · NIXL 传输与跨阶段数据搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-37\">三十七 · 通信何时成为瓶颈：三个可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-38\">三十八 · 与调度目标的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-39\">三十九 · 并行切分与通信瓶颈：这套调度逻辑在哪里失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-40\">四十 · 精度塌陷：从数值漂移到奖励信号失真</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-41\">四十一 · OOM 与 KV 预算：回压触发点才是真故障点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-42\">四十二 · 批抖动：分组策略在负载拐点处的振荡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-43\">四十三 · 尾延迟：长尾组隔离后的排队放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-44\">四十四 · 静默降级：没有告警的吞吐换精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-45\">四十五 · 回滚与定位顺序：从指标到决策日志</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-46\">四十六 · 运行时回压的失效边界与可观测性缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-47\">四十七 · 口径缺失下的“可比性”判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-48\">四十八 · 模型与硬件档位：未给出即不可外推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-49\">四十九 · batch、并发与负载分布：分母藏在分布里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-50\">五十 · 指标语义：TTFT、TPOT、吞吐、显存、功耗各自的口径陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-51\">五十一 · 哪些提升不可比：三类典型误读</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-52\">五十二 · 工程判断：把这篇论文放在什么位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-53\">五十三 · 迁移的第一道坎：调度器读什么，决定它能搬多远</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-54\">五十四 · RL 侧耦合是硬约束：脱离 rollout 语义就失去一半机制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-55\">五十五 · 规模上限：分组粒度与状态读取频率决定天花板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-56\">五十六 · 不适用区：KV 不是瓶颈、或尾延迟不由批构成决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-57\">五十七 · 迁到 Blackwell 栈时要补的三件事</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-58\">五十八 · 边界内的正确用法：把调度器当约束执行器而非优化器</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:551px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 551.0 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">RL训练侧发出批量生成请求，携带样本标识与长度信息进入调度入口。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器读取当前KV缓存占用与批内长度分布，决定是否复用前缀并分组。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">rollout引擎按分组执行批量生成，长尾样本被标记并进入单独队列。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">生成结果送入奖励模型与验证器推理，作为独立请求流复用同一调度逻辑。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器根据运行时负载回压rollout侧，控制并发以维持吞吐与SLO。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">完成的样本回传训练侧，权重同步与异步流水线细节未给出。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-1\">一 · 现场：一条被长尾样本拖住的在线链路</h3>\n<p>设想一个已经上线的推理服务：前端是对话产品，后端是若干台 GPU 节点，模型在 Blackwell 档位上以连续批处理（continuous batching）方式跑解码。请求长度分布极度不均——大部分请求在几百 token 内结束，少数请求要生成数千 token，还有一部分请求共享很长的系统提示前缀。调度器每一轮从等待队列里挑请求拼成一个 batch，交给引擎执行一次前向，然后回收已完成的序列、补入新请求。这套机制在纯在线服务里已经相当成熟：分页 KV cache 让显存按块分配，前缀共享让相同系统提示的请求复用同一段 KV，连续批处理让解码步之间不空转。</p>\n<p>但这条链路一旦被嵌入强化学习后训练的 rollout 环节，问题就出现了。RL 迭代需要一批样本，rollout 引擎批量发起生成请求，其中长尾样本决定了整批何时能收齐——只要有一个样本还在解码，这一批就无法进入奖励模型与验证器打分，也就无法回传训练侧。与此同时，奖励模型和验证器本身也是推理请求，它们和 rollout 的生成请求抢同一批 GPU。旧做法是把两侧当成两条独立流水线：rollout 引擎自己管一套批调度，服务侧调度器管另一套，中间靠队列和文件系统传递结果。这种解耦在工程上简单，代价却直接落在三个指标上。</p>\n<p>延迟上，长尾样本把整批的完成时间拉到最慢那个样本的量级，而这段时间里 GPU 的算力利用率随 batch 内已完成序列的减少而下降。吞吐上，两侧调度目标不一致：rollout 想让长尾尽快结束以降低 off-policy 陈旧度，服务侧想让吞吐最大、尾延迟可控，于是同一张卡上的两套策略互相拆台。显存上，两套调度各自持有 KV 预算，前缀共享难以跨阶段生效——rollout 阶段预填好的前缀，到了验证器推理阶段因为调度器不感知运行时状态而无法复用，只能重复预填。重复预填不是零成本：它既占算力又占带宽，在长上下文场景下这一项能吃掉相当比例的有效吞吐。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-2\">二 · 旧方案的结构性盲点：调度器看不见运行时</h3>\n<p>旧方案的核心问题不是某个参数没调好，而是调度决策的输入里缺少运行时状态。主流调度器在拼 batch 时通常只看两样东西：等待队列里的请求到达顺序，以及一个粗粒度的显存水位。它不知道当前 batch 内序列长度的分布形态，不知道哪些请求共享可复用的前缀，也不知道 KV 缓存的实际占用曲线会在哪一步逼近预算。于是分组策略退化为先来先服务加长度上限截断，KV 复用退化为按请求粒度各自预填。</p>\n<p>把这件事写成目标函数就很清楚。设调度策略为 π，旧方案实际上在解一个只看单侧的优化：</p>\n<div class=\"formula\">$$\\text{调度目标}=\\arg\\max_{\\pi}\\ \\mathbb{E}\\left[\\frac{\\text{吞吐}}{\\text{尾延迟}}\\right]\\quad \\text{s.t.}\\ \\text{KV占用}\\le \\text{预算}$$</div>\n<p>这个式子里，吞吐与尾延迟都只统计单侧——要么是 rollout 侧的样本完成速率，要么是服务侧的请求吞吐。约束项 KV 占用也只在单侧预算内成立。真正需要的是把两侧放进同一个期望里，让 rollout 的长尾样本、奖励模型请求、验证器请求共享同一个 KV 预算与同一个尾延迟口径。旧方案做不到这一点，因为两侧调度器之间没有运行时状态的交换通道：rollout 引擎不知道服务侧 KV 还剩多少，服务侧调度器也不知道 rollout 这一批里有多少长尾样本正在占用解码槽位。</p>\n<p>具体代价可以用一个场景说明。假设一个 batch 里有 64 条序列，其中 60 条在 200 步内完成，4 条要跑 2000 步。连续批处理会在前 200 步保持高 occupancy，之后 batch 缩到 4 条，GPU 的矩阵乘维度骤降，算力利用率塌陷，而这 4 条序列仍然按原来的并发度占着解码槽位与 KV 块。若调度器能读到“批内长度分布”，它本可以在拼 batch 时就把这 4 条长尾单独成组、降低并发，让短序列组先跑完释放 KV，长尾组用更小的 batch 慢慢推进。旧方案没有这个输入，只能让整批一起等。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-3\">三 · 解耦的隐性账单：KV 复用与前缀共享跨不过阶段边界</h3>\n<p>前缀共享是旧方案里最容易被低估的一项。在线服务中，大量请求共享同一段系统提示，分页 KV cache 让这段前缀只预填一次、后续请求按块引用。但 rollout 阶段与服务阶段的调度器各自管理自己的 KV 池，前缀的块标识不互通，于是同一段系统提示在 rollout 生成时预填一次，在验证器打分时又预填一次。重复预填的代价随前缀长度线性增长，在长系统提示加多轮对话的场景下，这部分算力本可以用来解码更多 token。</p>\n<p>更麻烦的是 KV 占用的时间维度。旧方案里，rollout 引擎为了尽快收齐一批样本，倾向于把并发拉满，KV 占用在短时间内冲到高位；服务侧调度器看到水位高就压低自己的 batch，导致在线请求尾延迟上升。两侧都没有一个统一的回压机制，只能各自设阈值、各自触发限流，结果是振荡：rollout 冲高、服务侧收缩、rollout 完成一批后释放、服务侧再扩张。这种振荡在监控上表现为尾延迟的周期性尖峰，工程上很难靠调参消除，因为根因是两套控制回路没有耦合。</p>\n<p>用伪代码描述旧方案的调度循环，盲点一目了然：</p>\n<ul>\n<li>从等待队列按到达顺序取请求，截断到长度上限，拼成 batch；</li>\n<li>查询本地 KV 池水位，若超过阈值则拒绝新请求入批；</li>\n<li>执行一步前向，回收已完成序列，释放其 KV 块；</li>\n<li>重复，直到队列空或本轮配额用完。</li>\n</ul>\n<p>这个循环里没有“批内长度分布”这一项，没有“可共享前缀的请求聚类”这一项，也没有“另一侧请求流的负载”这一项。三项缺失分别对应长尾拖累、重复预填、两侧争抢三个痛点。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-4\">四 · 为什么非改不可：RL 后训练把矛盾放大</h3>\n<p>纯在线服务里，上述盲点还能靠过供给（over-provisioning）掩盖：多留几张卡、KV 预算放宽、SLO 定得松一点。RL 后训练把这个缓冲吃掉了。rollout 是批量、周期性、突发性的负载，每一轮迭代都要在有限时间内生成足够样本；奖励模型与验证器推理又叠加在同一批 GPU 上。若调度器不感知运行时状态，off-policy 陈旧度会随长尾样本的等待时间上升——样本生成得越慢，策略更新时用到的数据越旧，训练信号的有效性下降。这不是一个可以靠加卡解决的问题，因为加卡只提高吞吐上限，不改变长尾样本决定整批完成时间这一事实。</p>\n<p>显存侧的账同样紧。RL 后训练中，rollout 的 KV 占用与验证器的 KV 占用在同一张卡上叠加，分页机制如果没有跨阶段的块复用，同一段前缀会被反复预填。假设前缀长度为 L、批内共享该前缀的请求数为 n，重复预填的算力代价约为 (n−1)·L 个 token 的前向量级——这个量级在 n 较大、L 较长时不可忽略，而旧方案连“哪些请求共享前缀”这个信息都没有传给调度器。带宽侧，重复预填意味着重复从 HBM 读权重与激活，在 Blackwell 的高带宽档位上这仍然是实打实的占用。</p>\n<p>功耗与散热是容易被忽略的第四本账。长尾阶段 batch 缩小、算力利用率塌陷，但 GPU 仍在高时钟下空转，能效比急剧恶化。一个 batch 从 64 条缩到 4 条却继续占着 SM 与解码槽位，等于用满功耗换极低有效吞吐。调度器若能看到长度分布并把长尾单独成组、降低并发，就能让短序列组跑满、长尾组用低占用推进，整体能效比改善。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-5\">五 · 一个具体例子：同一批样本在两种调度下的路径差异</h3>\n<p>取一次 RL 迭代的样本批：128 条生成请求，长度分布为重尾——约四分之三在数百 token 内结束，其余延伸到数千 token；其中一半请求共享一段长系统提示。旧方案下，调度器按到达顺序拼 batch，前缀共享只在单请求粒度生效，长尾样本与短样本混在同一 batch 里。前若干步 occupancy 高，随后 batch 逐步缩水，最后剩下少数长尾序列独占解码槽位，整批完成时间由最慢样本决定。验证器推理在另一条流水线上排队，同一段系统提示被再次预填。整条链路的尾延迟由长尾样本与验证器排队共同决定，而调度器对此一无所知。</p>\n<p>运行时感知的调度路径不同：调度入口先读当前 KV 占用与批内长度分布，把短序列与可共享前缀的样本合并成一组以复用 KV，长尾样本单独成组并降低并发；rollout 引擎按组执行批量生成，生成结果作为请求送入奖励模型与验证器，后者复用同一调度入口按运行时负载排队；当 KV 占用接近预算时，调度器回压 rollout 侧并发。这条路径的关键不是某个新算子，而是把“批构成、KV 占用、请求长度分布”这三项运行时状态变成调度决策的显式输入。代价是调度器每轮多一次状态读取与分组计算，收益是长尾不再拖慢整批、前缀不再重复预填、两侧不再各自振荡。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>旧方案（两侧解耦）</th><th>运行时感知调度</th></tr></thead><tbody><tr><td>调度输入</td><td>到达顺序、本地 KV 水位</td><td>批内长度分布、KV 占用、跨阶段请求流</td></tr><tr><td>长尾处理</td><td>与短样本混批，整批等待</td><td>单独成组、降低并发</td></tr><tr><td>前缀共享</td><td>单请求粒度，跨阶段失效</td><td>按可共享前缀聚类，跨阶段复用</td></tr><tr><td>回压</td><td>两侧各自设阈值，易振荡</td><td>统一入口按运行时负载回压</td></tr><tr><td>主要代价</td><td>尾延迟尖峰、重复预填、能效恶化</td><td>每轮状态读取与分组计算开销</td></tr></tbody></table>\n<p>这张表只描述机制差异，不给出任何收益数字——材料未提供数据集、基线、硬件档位与量化方案，吞吐提升倍数与尾延迟下降比例均不可核验。能确认的是设计意图：把 rollout、奖励模型与验证器推理放进同一运行时感知框架，让调度决策读到 KV 占用与批构成，而不是只看到队列顺序。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-6\">六 · 工程判断：改的是调度入口，不是加一张卡</h3>\n<p>对已经在 Blackwell 上部署推理栈的团队，这一部分给出的判断是具体的：当 rollout 与服务共用 GPU 时，先检查调度器的输入里有没有“批内长度分布”和“跨阶段 KV 占用”这两项。若没有，长尾拖累与重复预填就是结构性成本，加卡只能抬高吞吐上限、不能消除尾延迟尖峰。改造的落点在调度入口——让奖励模型与验证器推理作为独立请求流接入同一入口，让分组决策读取运行时状态，让回压在 KV 占用接近预算时统一触发。这三件事都不依赖新的数值精度或新的 MMA 指令，属于调度层的工程改动，但其收益直接体现在尾延迟与有效吞吐上。</p>\n<p>需要留意的缺口同样明确：材料未给出长尾判定阈值、队列长度上限、回压触发阈值与恢复策略，也未给出权重同步频率与异步流水线深度，因此调度器与 rollout 引擎的交互细节无法复现；硬件档位与量化方案缺失，NVFP4 下的采样稳定性与数值精度对调度决策的影响无法评估。这些缺口决定了后续只能把该工作当作机制方向的参考，而不能当作数据来源。真正落地时，分组算法与 KV 复用命中率需要在自己的请求分布上实测，而不是照搬论文的定性描述。</p>\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-7\">七 · 请求长度分布是调度器的第一手输入</h3>\n<p>在 Slim Scheduler 的设定里，调度入口最先读取的不是请求优先级标签，而是两个运行时量：当前 KV 缓存占用与批内序列长度分布。这个选择把负载形态从“外部统计特征”变成了“调度决策的即时输入”。对 CNN 推理服务而言，长度分布的意义与 LLM 不同——卷积网络的激活显存主要由特征图分辨率与批大小决定，序列长度更多体现在样本维度（多帧、多尺度输入、多裁剪）而非自回归 token 数；但在 RL rollout 侧，生成长度直接决定解码步数与 KV 增长曲线。两类长度混在同一调度入口时，分布形态决定了分组是否可行。</p>\n<p>可核查的测量口径必须落到分位数而非均值。工程上应记录每个请求的长度、到达时刻、进入调度队列时刻、首次执行时刻与完成时刻，按批内长度计算 P50/P90/P99 与最大最小比，并单独统计“长尾判定”所依据的阈值落在哪个分位。材料未给出具体分布形态与分位数，因此本部分只能给出测量框架而不能给出数值结论。一个具体例子：若某批内长度分布呈双峰——短样本集中在低分位、少量长尾样本跨越两个数量级——则按均值切分会让长尾样本与短样本同组，短样本完成后执行单元空转等待长尾，整批尾延迟被单条样本绑架。这正是调度器把长尾样本单独成组的动机。</p>\n<div class=\"formula\">$$\\text{批内离散度}=\\frac{P99(\\ell)}{P50(\\ell)},\\qquad \\text{分组收益}\\propto \\frac{\\text{组内长度方差}}{\\text{组间长度方差}}$$</div>\n<p>代价侧：长度分布越离散，分组带来的 KV 复用机会越多，但分组本身引入调度开销与批内碎片；若分组过细，批大小下降，执行单元利用率与吞吐同步下降。这是负载形态塑造方案的第一条路径——分布离散度决定分组粒度，分组粒度又反过来限制了可达到的批大小。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-8\">八 · 并发与批大小：回压是双向约束</h3>\n<p>Slim Scheduler 明确在 KV 占用接近预算时回压 rollout 侧并发。这条机制把并发从“配置项”变成了“运行时被控量”。可核查口径应包含：并发请求数的时间序列、批大小的时间序列、KV 占用率的时间序列，以及三者与回压触发时刻的对齐关系。材料未给出并发上限、批大小数值或 token 上限，也未给出回压触发阈值与恢复策略，因此无法量化回压频率与恢复滞后。</p>\n<p>机制上，回压是一个闭环：调度器监测 KV 占用，占用上升则降低 rollout 发起批量生成的并发，占用回落则放开。问题在于恢复策略未被描述——若回压后立即放开，占用会在阈值附近振荡；若滞后放开，则吞吐在低占用区间被无谓压制。工程判断上，回压应带迟滞区间（进入阈值与退出阈值分离），并把回压事件计数作为一等监控指标，否则失败模式不可观测。</p>\n<p>代价侧：并发越高，KV 占用增长越快，前缀共享的命中窗口越短（缓存被新请求挤出），复用率下降；并发越低，批大小不足，矩阵乘单元利用率下降，单位 token 的能耗上升。对 Blackwell 档位而言，材料未给出硬件配置，无法判断回压对 SM 利用率与功耗的实际影响，只能定性指出：回压是吞吐与显存之间的直接交换，且交换比率随长度分布变化。一个具体例子：当批内长尾样本占比升高时，同样并发下 KV 占用增长更快，回压更早触发，rollout 侧有效并发被压缩，off-policy 陈旧度随之上升——负载形态通过回压反向塑造了训练侧样本的新鲜度。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-9\">九 · SLO 与长尾：尾延迟的分母问题</h3>\n<p>论文给出的调度目标形式为吞吐与尾延迟之比的最大化，约束为 KV 占用不超预算。这个目标函数的结构值得深读：尾延迟在分母，意味着任何降低尾延迟的动作都被放大计分，而吞吐在分子只线性计分。可核查口径必须明确尾延迟的分位数定义（P99 还是最大）、统计窗口（滑动窗口长度）、以及是否按请求类型分别统计——rollout 生成请求与验证器推理请求的尾延迟语义不同，混算会掩盖验证器侧的排队代价。</p>\n<div class=\"formula\">$$\\text{调度目标}=\\arg\\max_{\\pi}\\ \\mathbb{E}\\left[\\frac{\\text{吞吐}}{\\text{尾延迟}}\\right]\\quad \\text{s.t.}\\ \\text{KV占用}\\le \\text{预算}$$</div>\n<p>长尾样本被单独分组并降低并发，这是把尾延迟从“整批等待”转为“独立队列等待”的手段。但材料未给出长尾判定阈值与队列长度上限，因此无法判断：长尾队列自身是否会形成新的尾延迟源（队列积压），以及长尾样本被延后处理对 off-policy 陈旧度的定量影响。工程上应记录长尾队列的到达率、服务率与等待时间分布，并与主队列对比；若长尾队列等待时间超过主队列尾延迟，则分组策略只是把长尾从批内转移到了队列间，并未消除。</p>\n<p>代价侧：尾延迟改善通常以吞吐为代价——降低长尾并发意味着执行单元在长尾样本上利用率不足。对 RL 侧，长尾样本完成慢会拖慢整批样本回传，进而拖慢一次迭代的墙钟时间；论文把“长尾样本尽快完成以降低 off-policy 陈旧度”列为 rollout 侧目标，说明尾延迟在这里不只是服务指标，还是训练效率指标。一个具体例子：若一次迭代需一批样本，其中少量长尾样本单独排队，主队列样本先完成回传，训练侧可先对已完成部分做前向与奖励计算，长尾样本后到后补——这要求训练侧支持部分批次的流水线，材料未给出该机制细节。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-10\">十 · 验证器请求流：被忽略的负载维度</h3>\n<p>奖励模型与验证器推理作为独立请求流接入同一调度入口，这是 Slim Scheduler 把负载形态统一化的关键一步。可核查口径应包含：验证器请求占总请求的比例、其批大小分布、其与 rollout 生成请求的到达时间相关性。材料未给出这些数值，因此验证器侧吞吐代价不明。</p>\n<p>机制上，验证器请求与 rollout 生成请求共享调度逻辑，意味着前缀共享与 KV 复用可能跨两类请求生效——若验证器对生成结果做打分时复用生成阶段的前缀缓存，可省去重复预填。但这也带来竞争：验证器请求若与 rollout 请求同组，其长度分布不同，分组收益下降；若单独成组，则调度入口需维护多队列，队列间优先级未给出。工程判断上，验证器请求应被视为“短、高优先级、可批量”的流，与“长、可分组、可延后”的 rollout 流分开统计 SLO，否则统一目标函数会掩盖两类流的差异。</p>\n<p>代价侧：验证器推理的加入提高了调度入口的请求异构度，分组决策的搜索空间变大，调度开销上升；同时验证器请求占用 KV 预算，压缩了 rollout 侧可用缓存，回压更易触发。一个具体例子：若验证器请求到达集中在 rollout 批次完成时刻（同步打分），则形成周期性负载尖峰，KV 占用瞬时冲高，回压被频繁触发——这种相关性是可测量的，应作为负载形态的一部分记录。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-11\">十一 · 负载与方案的双向塑造：可核查的测量清单</h3>\n<p>负载形态塑造方案：长度分布离散度决定分组粒度，并发水平决定回压频率，长尾占比决定尾延迟的分母大小，验证器请求比例决定调度入口的异构度。方案反过来限制负载：分组过细压低批大小，回压压低有效并发，长尾队列积压改变到达率，KV 预算约束前缀共享命中窗口。这个双向关系是 Slim Scheduler 的核心张力，也是其缺少数字时最难评估的部分。</p>\n<p>可核查测量清单应至少包含以下条目，且每条都需带时间戳与请求标识以便对齐：</p>\n<ul>\n<li>请求长度分位数（P50/P90/P99/最大）与批内离散度，按请求类型分开统计。</li>\n<li>并发请求数、实际批大小、KV 占用率三条时间序列，标注回压进入与退出时刻。</li>\n<li>尾延迟分位数定义、统计窗口、按类型分列的尾延迟，以及长尾队列等待时间分布。</li>\n<li>前缀共享命中率与复用长度，需与 KV 淘汰策略关联记录（材料未给出淘汰策略，此项只能标记为缺口）。</li>\n<li>验证器请求占比、到达时间与 rollout 完成时刻的相关性、验证器侧排队时间。</li>\n<li>off-policy 陈旧度代理指标：样本生成完成时刻与训练消费时刻之差，按是否长尾分组分列。</li>\n</ul>\n<p>代价侧：上述清单中每一项都对应一个工程开销——分位数统计需要滑动窗口内存，时间序列对齐需要请求级追踪，陈旧度代理需要训练侧打点。这些开销本身会占用运行时资源，测量粒度越细，对被测量系统的扰动越大。工程判断上，应把测量打点放在调度入口与队列边界，而非执行单元内部，以降低扰动。</p>\n<p>一个具体例子：若测量显示回压事件频率与长尾占比高度相关，而长尾队列等待时间并未低于主队列尾延迟，则说明分组策略的收益被队列积压抵消，此时应调整长尾判定阈值而非继续加大分组粒度。这个判断只能由上述清单支撑，材料未给出任何数字，故本部分只能给出判断路径而非结论。</p>\n<p>最后落在机制上：Slim Scheduler 把 KV 占用与批内长度分布作为调度决策的即时输入，使负载形态不再是离线假设而是在线被控量；其代价是调度入口必须承担请求级追踪与回压闭环的运行时开销，而这一开销的量化恰恰依赖材料未给出的并发上限、回压阈值与淘汰策略。对 Blackwell 部署而言，在缺少硬件档位与量化方案的情况下，唯一可核验的工程动作是把上述测量清单落到调度入口，用长度分布离散度与回压事件频率两个量先刻画负载，再谈分组与复用的收益。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-12\">十二 · 负载形态与调度边界的相互塑形</h3>\n<p>该方案对负载的适应完全建立在两个可读运行时量上：批内序列长度分布与KV缓存占用。调度器把短序列与可共享前缀的样本并组以复用KV，把长尾样本单独成组并压低并发。这带来一个直接边界：分组收益取决于长度分布是否双峰。若长度分布近似单峰，长尾组与短组规模都过小，分组本身引入的调度开销与空转反而吃掉复用收益。可核查的测量口径应固定为：按请求记录输入token数的分位数（p50/p90/p99）与直方图、组内长度方差、前缀命中长度与命中率、每组实际并发数、KV占用随时间的曲线。材料未给出这些数值，因此只能定性判断：当p99/p50比值不够大时，单独分组的尾延迟收益不可核验。</p>\n<div class=\"formula\">$$\\text{组收益}\\approx \\frac{\\text{复用节省的预填token}}{\\text{组内最长序列token}+\\text{分组切换开销}}$$</div>\n<p>负载反过来限制方案的地方在回压环节。调度器在KV占用接近预算时回压rollout并发，但材料未给出触发阈值与恢复策略，这意味着存在一个失效条件：回压过晚则KV溢出导致重算预填，过早则rollout批被切碎、off-policy陈旧度上升。对RL侧而言，陈旧度代价可用“样本生成完成时刻与策略版本时刻之差”来度量，而调度器只看KV占用，不直接看陈旧度，二者目标在此处并未真正统一。奖励模型与验证器推理作为独立请求流接入同一入口，其请求比例与SLO未给出，若验证器请求突增，会与rollout长尾组争抢同一KV预算，形成优先级反转。</p>\n<table class=\"mini\"><thead><tr><th>可核查口径</th><th>用途</th><th>材料状态</th></tr></thead><tbody><tr><td>输入长度分位数与直方图</td><td>判断分组是否有收益</td><td>未给出</td></tr><tr><td>前缀命中长度/命中率</td><td>量化KV复用节省</td><td>未给出</td></tr><tr><td>回压触发阈值与恢复策略</td><td>定位失效点</td><td>未给出</td></tr><tr><td>验证器请求占比与SLO</td><td>评估争抢代价</td><td>未给出</td></tr></tbody></table>\n<p>系统代价落在三处：分组切换带来的调度空转、长尾组低并发造成的SM利用率下降、以及KV预算紧张时的预填重算。材料未给出硬件档位与量化方案，因此无法判断NVFP4下采样稳定性是否会影响长度分布的可预测性——采样长度本身随策略变化，长度分布并非静态输入，这使“读取长度分布再分组”的决策存在滞后。工程判断是：该方案适合长度分布稳定且前缀共享明显的负载，一旦分布漂移或验证器流量占比升高，运行时感知逻辑需要额外的陈旧度与优先级约束，否则吞吐与尾延迟的权衡会退化为对KV占用的被动反应。</p>\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-13\">十三 · 从调度决策到 kernel 选择：运行时状态如何落到算子层</h3>\n<p>调度器读到的批内长度分布与 KV 占用，最终必须翻译成算子层的三个选择：用哪个 MMA 形状、用什么数据类型、累加器放哪里。Slim Scheduler 的运行时感知逻辑在算子层的落点是分组——短序列与可共享前缀的样本合并成一组，长尾样本单独成组。合并组意味着更大的有效 token 数，可以走更宽的 tile；单独成组的长尾样本则被迫走窄 tile 或小批量路径，Tensor Core 利用率下降。这一代价不是调度器能直接看到的：调度器只看到尾延迟与 KV 占用，而算子层看到的是 tile 填充率。两者之间的映射关系是：</p>\n<div class=\"formula\">$$\\text{tile 填充率}=\\frac{\\sum_{i\\in \\text{组}} L_i}{N_{\\text{tile}}\\cdot T_{\\text{tile}}}$$</div>\n<p>其中 $L_i$ 是组内第 $i$ 条序列的有效长度，$N_{\\text{tile}}$ 是该组切出的 tile 数，$T_{\\text{tile}}$ 是单个 tile 的 token 容量。分子由调度分组决定，分母由 kernel 的 tile 形状决定。长尾样本单独成组时，$N_{\\text{tile}}$ 被撑大而分子不变，填充率塌陷，SM 上的 MMA 流水线出现气泡。这就是为什么调度器对长尾样本\"降低并发\"的决策在算子层等价于\"接受更低的 Tensor Core 占用率\"——尾延迟的改善是用算力利用率换来的，这笔账在材料中没有给出数字，但机制上必然存在。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-14\">十四 · 数据类型谱系：FP16/BF16 到 FP8 再到 NVFP4 的取舍</h3>\n<p>Blackwell 第五代 Tensor Core 支持的推理数据类型从 FP16/BF16 一路压到 FP8 与 NVFP4。精度下降带来的是每 SM 每周期 MMA 吞吐的提升与显存带宽压力的下降，代价是数值误差进入累加链。对 Slim Scheduler 这类以批调度为核心的系统，数据类型选择不是全局开关，而是按组切换：合并组内的短序列前缀共享部分可以走低精度，长尾样本的生成若涉及采样稳定性则倾向保留更高精度。材料明确未给出量化方案的使用位置，因此这里只能给出判断框架而非结论。</p>\n<p>关键的量是每次 MMA 的累加误差累积。设一次矩阵乘的归约长度为 $K$，输入量化误差为 $\\epsilon_x$、$\\epsilon_w$，则输出误差的一阶上界为：</p>\n<div class=\"formula\">$$\\|\\Delta Y\\| \\lesssim \\sqrt{K}\\,\\big(\\epsilon_x\\|W\\|+\\epsilon_w\\|X\\|\\big)+\\epsilon_{\\text{acc}}\\sqrt{K}\\,\\|X\\|\\|W\\|$$</div>\n<p>三项分别对应激活量化、权重质量化与累加器精度。NVFP4 的块级缩放把 $\\epsilon_x,\\epsilon_w$ 控制在每 16 元素共享一个缩放因子的粒度上，但 $\\epsilon_{\\text{acc}}$ 取决于累加器是 FP32 还是更低。Blackwell 的 tcgen05 MMA 在 TMEM 中累加，累加精度与累加器驻留位置绑定——这是下一节要展开的机制。对 RL rollout 而言，误差的直接后果是采样分布偏移：低精度 logits 经过 softmax 后尾部概率被压缩，长尾样本的生成概率被系统性低估，而长尾样本恰恰是调度器单独分组要保护的对象。精度与调度在这里发生了耦合，材料没有给出 NVFP4 下采样稳定性的任何数据，这一耦合只能作为工程风险标注。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-15\">十五 · tcgen05、TMEM 与 2-SM MMA：累加器住在哪里</h3>\n<p>Blackwell 的 tcgen05 指令族把 MMA 的累加器从寄存器文件搬到 Tensor Memory（TMEM）。TMEM 是每个 SM 上独立的一块片上存储，专供 Tensor Core 读写，容量以列为单位组织。这一搬家的直接后果是：寄存器压力从 MMA 路径上卸下，kernel 可以把更多寄存器留给 epilogue 与地址计算；代价是累加结果的读写必须经过 TMEM 的加载/存储指令，epilogue 的延迟结构改变。</p>\n<p>2-SM MMA 是另一条关键机制：一对 SM 通过协作指令共同完成一次更大的 MMA，tile 形状跨 SM 拼接。对调度器而言，这意味着一个合并组的最小可执行粒度被抬高——2-SM MMA 要求两个 SM 的 tile 同时就绪，组内 token 数不足时要么退化到单 SM 路径，要么等待配对。伪代码层面的约束是：</p>\n<div class=\"formula\">$$\\text{可执行}=\\big(N_{\\text{tile}}\\ge 2\\big)\\ \\wedge\\ \\big(\\text{TMEM 列预算}\\ge C_{\\text{acc}}\\cdot N_{\\text{tile}}\\big)$$</div>\n<p>$C_{\\text{acc}}$ 是每个 tile 累加器占用的 TMEM 列数。这个合取式说明：调度器把长尾样本单独成组、压低并发，在 2-SM MMA 路径上可能直接导致组不可执行或被迫走低效路径。TMEM 列预算则是并发的硬上限——同一 SM 上并行的 MMA 数量受 TMEM 容量约束，而不是受寄存器或 shared memory 约束。调度器回压 rollout 并发时，若回压粒度与 TMEM 预算不对齐，会出现\"预算还有余量但组已无法配对\"的空转。材料未给出 TMEM 预算与分组粒度的关系，这是该工作与 Blackwell 特性之间最明显的未验证接口。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-16\">十六 · 累加精度与误差在调度链路中的传播</h3>\n<p>误差不会停在单个 kernel 里。Slim Scheduler 的链路是 rollout 批量生成 → 奖励模型 → 验证器推理，三段各自可能用不同精度。生成段的低精度 logits 误差进入采样，采样结果作为文本进入奖励模型，奖励模型的打分误差再进入验证器。三段误差不是简单相加，而是通过离散采样被放大或截断：一个被低精度压掉的长尾 token 一旦没被采样出来，后续两段根本看不到它，误差表现为\"样本缺失\"而非\"数值偏移\"。</p>\n<p>把这条链写成误差传播的近似式，设生成段输出分布为 $p$、参考分布为 $p^\\*$，则 KL 偏差的一阶近似为：</p>\n<div class=\"formula\">$$D_{\\mathrm{KL}}(p\\,\\|\\,p^\\*)\\approx \\tfrac{1}{2}\\sum_v \\frac{(\\Delta \\ell_v)^2}{p_v}$$</div>\n<p>$\\Delta \\ell_v$ 是 token $v$ 的 logit 误差，$p_v$ 是其概率。分母 $p_v$ 说明：低概率 token 的 logit 误差被放大得最厉害——正是长尾样本所在的区域。这解释了为什么调度器把长尾样本单独分组保护，与精度策略必须联动：保护了调度优先级却用低精度生成，长尾样本的分布仍然被扭曲。工程代价上，这意味着若要在 NVFP4 下保住长尾采样，生成段可能需要对长尾组保留 FP8 或 BF16 路径，而合并组走 NVFP4——按组切换精度本身带来 kernel 启动与格式转换开销，这部分开销在材料中完全没有涉及。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-17\">十七 · 第五代 Tensor Core 的吞吐账与调度器的可见性</h3>\n<p>第五代 Tensor Core 在 FP8 与 NVFP4 上的每周期 MMA 吞吐相对前代提升，但调度器看不到这个提升——它只看到尾延迟与 KV 占用。两者之间的桥是\"每组每秒有效 token 数\"，它同时受 tile 填充率、数据类型吞吐与 TMEM 预算约束：</p>\n<div class=\"formula\">$$\\text{组吞吐}=\\frac{\\eta_{\\text{tile}}\\cdot \\text{MMA}_{\\text{rate}}(d)\\cdot N_{\\text{SM}}}{L_{\\text{avg}}}\\quad\\text{s.t.}\\ \\text{TMEM}\\le \\text{预算},\\ \\text{KV}\\le \\text{预算}$$</div>\n<p>$\\eta_{\\text{tile}}$ 是填充率，$\\text{MMA}_{\\text{rate}}(d)$ 是数据类型 $d$ 对应的每 SM MMA 速率，$L_{\\text{avg}}$ 是组内平均序列长度。这个式子把调度决策（分组影响 $\\eta_{\\text{tile}}$ 与 $L_{\\text{avg}}$）、精度决策（$d$ 影响 $\\text{MMA}_{\\text{rate}}$）与硬件约束（TMEM、KV 预算）放在同一目标下。Slim Scheduler 的调度目标 $\\arg\\max_\\pi \\mathbb{E}[\\text{吞吐}/\\text{尾延迟}]$ 若要真正落地，$\\pi$ 的动作空间必须包含精度档位与分组粒度两个维度，否则调度器在算子层是盲的。材料只给出调度器读取 KV 占用与长度分布，未给出它是否读取精度档位或 TMEM 占用，这是设计意图与可执行性之间的缺口。</p>\n<p>一个具体例子：假设合并组由若干短序列构成、前缀可共享，填充率高，走 NVFP4 + 2-SM MMA，吞吐接近峰值；长尾组只有少量长序列，填充率低，若仍走 2-SM 路径则配对失败，退化到单 SM 且 TMEM 列预算闲置。此时调度器的正确动作不是继续压低长尾组并发，而是把长尾组与另一个短组拼成可配对的 tile——这要求调度器理解 tile 形状而不只是序列长度。材料未描述这种跨组拼接，故该优化停留在机制推演层面。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-18\">十八 · 工程判断：精度与调度的耦合点在哪里</h3>\n<p>对在 Blackwell 上部署这类运行时感知调度的工程读者，可操作的判断有三条。其一，把精度档位作为调度动作空间的一维，而不是部署前的静态配置：合并组与长尾组用不同精度，前提是 kernel 支持按组切换且切换开销被摊销。其二，把 TMEM 列预算纳入回压触发条件，与 KV 占用并列——材料只提 KV 占用回压，遗漏了 TMEM 这一 Blackwell 特有的并发上限，回压阈值若只盯 KV 会在 TMEM 先耗尽时失效。其三，长尾样本的精度保护要有明确的判定阈值，否则\"单独分组\"只是调度层的动作，采样分布仍被低精度扭曲，尾延迟改善与样本质量之间形成隐性对冲。</p>\n<p>这三条的共同点是：调度器读取的运行时状态必须包含算子层状态（精度档位、TMEM 占用、tile 填充率），否则运行时感知只停留在请求层。Slim Scheduler 的材料把调度入口描述为读取 KV 占用与批内长度分布，未延伸到 Tensor Core 侧；在 Blackwell 上，这个延伸恰恰是吞吐与尾延迟能否同时兑现的分界线。tcgen05 的 TMEM 累加与 2-SM MMA 的配对约束，把\"分组\"从逻辑概念变成物理可执行性判断——调度决策与 kernel 可执行性之间的映射，是这套系统在 SM100/SM103 上最需要补测的一环。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-19\">十九 · 精度档位缺失下的调度边界：KV预算、长尾分组与验证器流的耦合代价</h3>\n<p>把调度目标写成<em>吞吐/尾延迟</em>的期望最大化并受KV占用约束，这个形式本身不依赖任何数值精度；但约束的左端——KV占用的字节数——恰恰由精度档位决定。同一批内序列长度分布下，FP16与NVFP4的每token KV字节数相差数倍，调度器读到的“占用接近预算”会在完全不同的绝对水位触发回压。材料未给出量化方案与缓存预算，因此公式中<em>KV占用≤预算</em>这一约束在Blackwell上的可行域无法标定：若按BF16估算预算，NVFP4部署下调度器会过早回压rollout并发，长尾样本的off-policy陈旧度反而上升；若按NVFP4估算，切回FP8时预算被击穿，前缀共享的分组在预填阶段即被拒绝，KV复用命中率塌陷。这是该方案第一个结构性边界——运行时感知的输入是字节数，而字节数的语义随精度漂移。</p>\n<p>长尾样本单独成组并降并发，是控制尾延迟的直接手段，但它与验证器推理流共享同一调度入口，代价在此处叠加。设批内第<em>i</em>组样本数为<em>n<sub>i</sub></em>、平均生成长度为<em>L<sub>i</sub></em>、单步解码代价为<em>c</em>，则该组占用调度时隙近似为<em>n<sub>i</sub>·L<sub>i</sub>·c</em>；长尾组被压低<em>n<sub>i</sub></em>后，其<em>L<sub>i</sub></em>不变而时隙被拉长，奖励模型与验证器请求若排在长尾组之后，验证器侧吞吐被同步拖慢。材料未给出验证器请求比例与批大小，因此无法判断“长尾优先还是延后”的净收益方向——当验证器流占比高时，把长尾组降并发等于把尾延迟从rollout侧转移到验证器侧，SLO并未改善，只是换了承担者。</p>\n<div class=\"formula\">$$\\text{组时隙}\\approx n_i\\cdot L_i\\cdot c,\\qquad \\text{回压条件}:\\ \\sum_i n_i\\cdot L_i\\cdot b_{\\text{kv}}\\ge B_{\\text{kv}}$$</div>\n<p>式中<em>b<sub>kv</sub></em>为每token KV字节数，直接由精度档位给出；<em>B<sub>kv</sub></em>为预算。该式说明回压触发点对<em>b<sub>kv</sub></em>线性敏感，而材料未给出<em>b<sub>kv</sub></em>与<em>B<sub>kv</sub></em>，故回压阈值、恢复策略与失败模式均不可核验。工程判断上，该方案在Blackwell部署的可移植性取决于两件事：调度器是否把精度档位作为显式输入而非隐含常量，以及长尾判定阈值是否随验证器流负载动态调整。材料对二者均无描述，因此它只能作为“运行时状态应进入调度决策”的机制方向，不能作为NVFP4采样稳定性或B200档位适用性的证据。</p>\n<table class=\"mini\"><thead><tr><th>缺失项</th><th>对调度决策的影响</th><th>可观测代价</th></tr></thead><tbody><tr><td>量化方案未给出</td><td>KV字节数语义漂移，回压阈值失准</td><td>并发过早或过晚回压，尾延迟与陈旧度双向恶化</td></tr><tr><td>长尾判定阈值未给出</td><td>分组边界不可复现</td><td>长尾组时隙拉长，验证器流排队加深</td></tr><tr><td>验证器请求比例未给出</td><td>优先/延后方向无法定</td><td>尾延迟在rollout与验证器间转移而非消除</td></tr></tbody></table>\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-20\">二十 · 显存账本的三个账户：权重、激活、KV</h3>\n<p>在 Blackwell 上做推理，显存不是一个池子，而是三个性质完全不同的账户。权重是只读的、静态的、可复制的；激活是瞬态的、随批大小与序列长度线性增长的；KV cache 是跨请求累积的、生命周期由调度策略决定的。Slim Scheduler 的运行时感知逻辑之所以成立，前提就是调度器能读到这三个账户的实时余额——材料里明确写了调度器读取“当前 KV 缓存占用与批内长度分布”，这本质上是在读第三个账户的余额，并据此反推前两个账户还能容纳多少并发。</p>\n<p>权重账户的占用由参数量与精度决定，与批无关。激活账户的峰值出现在 prefill 阶段，注意力中间结果与 MLP 中间结果叠加，规模约为 $B \\cdot S \\cdot d \\cdot L$ 量级，其中 $B$ 为批内序列数、$S$ 为序列长度、$d$ 为隐藏维、$L$ 为层数——这个量在长序列 prefill 时会瞬间吃掉数 GB，是调度器必须避开的尖峰。KV 账户则是 $2 \\cdot B \\cdot S \\cdot n_{kv} \\cdot d_{head} \\cdot L \\cdot b_{kv}$，其中 $n_{kv}$ 是 KV 头数（GQA 下远小于注意力头数）、$b_{kv}$ 是每元素字节数。三者的区别在于：权重不可回收，激活可即时释放，KV 只能通过淘汰或请求结束回收。调度器若只盯吞吐不看 KV 余额，就会出现“批排得下、KV 装不下”的假性容量。</p>\n<p>代价体现在这里：KV 账户一旦逼近预算，调度器回压 rollout 并发（材料确认了这一机制），直接后果是 rollout 侧的批量生成变慢、长尾样本完成时间拉长、off-policy 陈旧度上升。这是一个显存换新鲜度的权衡，而不是单纯的吞吐损失。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-21\">二十一 · 分页与压缩：把 KV 从连续块变成可调度单元</h3>\n<p>KV cache 的传统分配是按最大序列长度预留连续显存，这在 RL rollout 场景下极不划算——rollout 的样本长度分布长尾明显，材料虽未给出分位数，但明确提到长尾样本需单独分组。按峰值预留意味着大量显存被短样本浪费。分页机制把 KV 切成固定大小的 block（例如按 token 数切块），按需分配、按块索引，逻辑序列在物理上不连续。这样做的直接收益是：短样本只占它实际需要的块数，长尾样本按增长逐块追加，显存利用率从“按最长预留”变成“按实际占用”。</p>\n<p>分页带来的第二个能力是前缀共享。当多个 rollout 样本共享同一 prompt 前缀时，这些前缀对应的 KV block 可以被多个逻辑序列引用同一份物理块，引用计数归零才释放。Slim Scheduler 的“将短序列与可共享前缀的样本合并为一组以复用 KV”正是建立在这个块级引用模型上。可复算的收益上界是：若一组 $n$ 个样本共享长度为 $S_p$ 的前缀，节省的 KV 字节为 $(n-1) \\cdot S_p \\cdot 2 \\cdot n_{kv} \\cdot d_{head} \\cdot L \\cdot b_{kv}$。材料未给出前缀命中率与共享长度阈值，因此这个节省只能作为机制上界，不能当作实测收益。</p>\n<p>压缩是另一条路：量化 KV 到 FP8 甚至更低，把 $b_{kv}$ 减半或更多。代价是数值误差进入注意力打分，长上下文下误差累积更明显；材料明确未给出量化方案，因此不能声称该工作在 NVFP4 或 FP8 KV 下的采样稳定性。工程判断是：KV 量化省下的是容量与带宽，付出的是精度裕度，而 RL rollout 的奖励信号对数值漂移敏感，压缩必须与验证器侧的容错一起评估。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-22\">二十二 · 复用与卸载：跨阶段共享与容量换带宽</h3>\n<p>复用发生在两个层面。第一层是同一调度框架内的前缀共享，如上节所述，块级引用让 rollout 的批量生成与验证器推理可以命中同一份前缀 KV——材料确认奖励模型与验证器推理作为独立请求流接入同一调度入口，这意味着前缀共享有机会跨阶段生效，而不是在训练与推理解耦后被切断。第二层是分组复用：调度器按批内长度分布把可共享前缀的样本合并成组，组内一次 prefill 产出多份可引用的 KV，减少重复预填。材料把“减少空转与重复预填”列为设计目标，机制上对应的就是这两层。</p>\n<p>卸载则是把冷 KV 换出到主机内存或远端存储，用 PCIe/NVLink 带宽换 HBM 容量。代价可以写成一条不等式：换出再换入的字节量为 $2 \\cdot S \\cdot 2 \\cdot n_{kv} \\cdot d_{head} \\cdot L \\cdot b_{kv}$，若这段 KV 在换入后还要被再次访问，则有效带宽开销必须小于它带来的并发增益，否则卸载只是把延迟从显存转移到了链路上。在 GB200 NVL72 这类机架内，NVLink 5 的域内带宽让“远端 HBM 当二级缓存”在拓扑上可行，但材料未给出并行拓扑与卸载路径，因此这里只能给出判据而非配置。</p>\n<p>具体例子：一个长尾样本在生成到第 $S$ 个 token 时 KV 占用达到单样本预算上限，调度器有两个选择——淘汰该样本的中间块（丢失后需重算 prefill）或将其换出到主机内存（保留但占带宽）。前者牺牲算力，后者牺牲链路；Slim Scheduler 的材料只提到“长尾样本单独成组并降低并发”，没有描述淘汰或卸载策略，这正是其工程缺口之一。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-23\">二十三 · 带宽瓶颈在哪：HBM3e 的读放大</h3>\n<p>解码阶段的算术强度极低：每生成一个 token，需要把全部权重读一遍，而计算只有一次矩阵向量乘。设权重字节数为 $W$，HBM 带宽为 $BW$，则单 token 解码的权重读取下界时间为 $W/BW$。以 HBM3e 的单堆栈带宽量级计，权重读取是解码的硬下界，批大小只能摊薄它而不能消除它。KV 读取则随批内序列总长线性增长：每 token 需读 $B \\cdot S \\cdot 2 \\cdot n_{kv} \\cdot d_{head} \\cdot L \\cdot b_{kv}$ 字节。当 $B$ 增大，KV 读取项追上甚至超过权重项，此时瓶颈从“权重带宽”切换到“KV 带宽”。</p>\n<div class=\"formula\">$$\\text{解码每 token 时间下界} \\approx \\frac{W + B \\cdot S \\cdot 2 n_{kv} d_{head} L b_{kv}}{BW}$$</div>\n<p>这条式子给出调度器的判断依据：当批内平均序列长度 $S$ 上升，KV 项占比上升，继续加批的边际吞吐收益递减，而尾延迟上升。Slim Scheduler 的“按批内长度分布分组”在机制上就是控制这个比值——把长序列集中到低并发组，避免它们把 KV 读取项推高到拖慢整批。代价是长序列组的硬件利用率下降，短序列组则可能因并发过高而触发 KV 预算回压。带宽瓶颈的另一个来源是 prefill 的写放大：prefill 要写入全部 KV，写入带宽与读取带宽共享 HBM 通道，长 prompt 的 prefill 会短暂挤占解码的读带宽。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-24\">二十四 · 可复算的显存预算</h3>\n<p>下面给出一个只依赖符号的预算表，读者可代入自己模型的参数量、层数、KV 头数与精度字节数复算。表中不填任何未给出的实测数字，所有量都是可推导的表达式。</p>\n<table class=\"mini\"><thead><tr><th>账户</th><th>表达式</th><th>随什么增长</th><th>回收方式</th></tr></thead><tbody>\n<tr><td>权重</td><td>$P \\cdot b_w$（$P$ 参数量，$b_w$ 每参数字节）</td><td>固定</td><td>不可回收，可复制</td></tr>\n<tr><td>激活（prefill 峰值）</td><td>$\\approx B \\cdot S \\cdot d \\cdot L \\cdot b_a$</td><td>批大小、序列长度</td><td>即时释放</td></tr>\n<tr><td>KV（每序列）</td><td>$2 \\cdot S \\cdot n_{kv} \\cdot d_{head} \\cdot L \\cdot b_{kv}$</td><td>序列长度、层数、KV 头数</td><td>淘汰或请求结束</td></tr>\n<tr><td>KV（批内合计）</td><td>$\\sum_i 2 \\cdot S_i \\cdot n_{kv} \\cdot d_{head} \\cdot L \\cdot b_{kv}$</td><td>批内长度分布</td><td>分页引用计数</td></tr>\n<tr><td>前缀共享节省</td><td>$(n-1) \\cdot S_p \\cdot 2 n_{kv} d_{head} L b_{kv}$</td><td>共享组大小、前缀长度</td><td>引用归零释放</td></tr>\n</tbody></table>\n<p>预算约束就是调度目标里的那条：$\\text{KV占用} \\le \\text{预算}$。可复算的做法是：先由权重账户确定固定占用，再从 HBM 容量中扣除激活峰值的安全余量，剩余部分即为 KV 预算；把 KV 预算除以单序列每 token 的 KV 字节数，得到“等效可容纳 token 数”，再除以批内平均长度得到并发上界。这个上界就是调度器回压 rollout 并发时的参考线。材料未给出回压触发阈值与恢复策略，因此这条参考线只能作为设计方法，不能当作该论文的实测配置。</p>\n<p>具体例子：若某模型 $L$ 层、$n_{kv}$ 个 KV 头、每头 $d_{head}$ 维、KV 用 2 字节存储，则每 token 每序列的 KV 字节为 $2 \\cdot 2 \\cdot n_{kv} \\cdot d_{head} \\cdot L$。给定 KV 预算后，可容纳的总 token 数直接可算；当批内平均长度翻倍，并发上界减半——这正是长尾样本单独分组、降低并发的显存依据，而不是拍脑袋的调度偏好。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-25\">二十五 · 预算与调度的耦合判断</h3>\n<p>把显存账本和调度决策连起来看，Slim Scheduler 的机制方向是清楚的：调度器读 KV 余额与长度分布，分组决定复用，余额逼近预算时回压并发。但工程上真正决定成败的是三个未给出的参数——KV 预算占 HBM 的比例、前缀共享的实际命中率、回压的触发与恢复迟滞。前两个决定复用能省多少，第三个决定回压会不会引发振荡：若触发过晚，KV 溢出导致请求失败；若恢复过早，并发反复升降，尾延迟抖动反而放大。材料明确未描述失败模式，这意味着该工作的运行时感知逻辑在机制上自洽，但在容量规划上还缺一条可核验的闭环。</p>\n<p>对 Blackwell 部署而言，HBM3e 的容量决定了 KV 预算的绝对上限，而带宽决定了预算内的批大小上限；两者共同约束调度器的可行域。判断标准应落在：给定权重与激活余量后，KV 预算能否覆盖目标并发下的长度分布，若不能，则必须依赖前缀共享命中率或 KV 压缩来补足，而这两者在材料中均无数字支撑。因此本部分的显存预算只能作为复算框架，收益幅度仍停留在机制层面。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-26\">二十六 · 运行时感知调度的显存边界与失效条件</h3>\n<p>该方案的显存账本由三部分构成：rollout 批量生成的激活与采样缓冲、奖励模型与验证器推理的权重常驻、以及跨阶段共享的 KV 缓存。材料只给出“调度器读取 KV 占用与批内长度分布”这一机制，未给出预算数值、淘汰策略与分页粒度，因此可复算的只有结构关系：设总预算为 <span class=\"formula\">$$M_{\\text{total}} = M_{w} + M_{act}(b,\\ell) + M_{kv}(b,\\ell,h)$$</span>，其中 <span class=\"formula\">$$M_{kv} \\propto b \\cdot \\ell \\cdot h \\cdot d_h \\cdot 2$$</span>（K/V 两份，<span class=\"formula\">$$d_h$$</span> 为每头维度）。在 Blackwell 的 HBM3e 容量下，KV 项随批内长度分布的长尾迅速吃掉余量，而权重项是常量——这正是调度器必须把长尾样本单独分组的经济理由：长尾样本拉高 <span class=\"formula\">$$\\ell$$</span> 的均值却不提升有效吞吐，等价于用显存换空转。</p>\n<p>失效条件集中在回压逻辑。材料只写“占用接近预算时回压 rollout 并发”，未给出触发阈值与恢复策略。若阈值取得过紧，rollout 侧并发下降会直接拉长样本生成时间，抬高 off-policy 陈旧度；若取得过松，KV 复用与前缀共享的命中率被长尾序列挤掉，验证器推理请求排队变长。二者都表现为尾延迟恶化而非吞吐下降，监控上容易被误判为验证器侧瓶颈。工程判断是：回压必须与分组决策同频，否则“先分组、后回压”的两段式逻辑会在批边界处产生抖动。</p>\n<p>系统代价方面，奖励模型与验证器作为独立请求流接入同一入口，其请求比例与批大小材料未给出，因此验证器侧的显存占用无法从 rollout 账本中剥离；一旦验证器权重与 rollout 激活共卡，KV 预算实际被压缩，前缀共享的收益随之缩水。带宽侧，KV 复用的收益取决于命中长度而非命中次数，长尾样本单独成组意味着这部分序列几乎不参与共享，HBM 读写仍按全量走。表格给出可复算的定性账本：</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>随何变化</th><th>调度可调</th><th>失效表现</th></tr></thead><tbody><tr><td>权重常驻</td><td>模型与精度档位</td><td>否</td><td>压缩 KV 预算</td></tr><tr><td>激活/采样</td><td>批大小、序列长度</td><td>是（分组）</td><td>长尾拉高均值</td></tr><tr><td>KV 缓存</td><td>批内长度分布、头数</td><td>是（复用/回压）</td><td>命中率被长尾挤掉</td></tr></tbody></table>\n<p>边界在于：该方案没有给出量化方案与硬件档位，NVFP4 下采样稳定性与调度决策的耦合无法评估；KV 分页粒度、淘汰策略与卸载路径均缺失，因此“复用”只能停留在机制方向。对 Blackwell 部署而言，可迁移的判断是——把 KV 占用作为一等调度信号、把长尾序列隔离出共享池，这两条在 HBM3e 容量约束下成立；但回压阈值、验证器请求配比与权重同步频率必须由部署方自行标定，论文不提供可核验数字。</p>\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-27\">二十七 · 连续批处理的运行时判据：批构成决定复用边界</h3>\n<p>Slim Scheduler 的连续批处理不是“来一个塞一个”的朴素迭代级调度，而是把批构成本身当作决策变量。调度入口在每次组批前读取两个运行时量：当前 KV 缓存占用与批内序列长度分布。短序列与可共享前缀的样本被合并为一组，目的是让前缀共享在同一个批内真正生效——前缀共享的收益取决于同批内是否存在相同前缀的序列，跨批复用则受限于 KV 块的生命周期。若调度器不感知批构成，前缀共享只能在单请求维度退化为重复预填，这正是论文所指的“跨阶段复用难以生效”。</p>\n<p>用伪代码表达组批判据：对候选请求集合按前缀哈希聚类，簇内按长度排序，若簇内最短序列长度与最长序列长度之比超过阈值且簇的 KV 需求之和不超过剩余预算，则整簇入批；否则拆簇，长序列后置。这个判据的代价直接落在预填算力上：一次成功的簇内合并可把 N 次预填压缩为一次，省下的是 prefill 阶段的 MMA 周期与 KV 写入带宽；代价是组批延迟增加，因为调度器要等簇凑齐。对在线服务，组批等待直接计入首 token 时延（TTFT）；对 rollout，组批等待转化为样本完成时间的方差，进而影响 off-policy 陈旧度。</p>\n<p>具体例子：一个批内出现三条共享同一系统提示的请求，长度分别为 200、900、1400 token。若按到达顺序组批，第一条先单独预填，后两条各自重复预填共享段；若按簇合并，共享段只算一次，三条序列的 KV 前缀块指向同一物理页。省下的预填量约等于共享段长度乘以重复次数，但代价是 1400 token 那条要等 200 token 那条一起入批，TTFT 被拉长。调度器在这里做的不是优化单请求，而是选择让谁等。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-28\">二十八 · Chunked prefill 与解码的混批：把长预填切碎塞进解码间隙</h3>\n<p>chunked prefill 的作用是把一次长预填拆成若干 chunk，与正在解码的序列混在同一迭代里执行，使解码步不被长预填阻塞。Slim Scheduler 的运行时感知体现在 chunk 大小的选择上：chunk 上限不是固定常数，而是由当前批内解码序列的 KV 占用与剩余算力共同决定。解码序列占用 KV 越多，可用于预填 chunk 的算力越少，chunk 应相应缩小，否则单次迭代的时延被预填拖长，解码侧的交错 token 时延（ITL）出现尖峰。</p>\n<div class=\"formula\">$$\\text{chunk}^*=\\arg\\min_{c}\\ \\max\\bigl(\\text{ITL}_{\\text{p99}}(c),\\ \\text{TTFT}_{\\text{p99}}(c)\\bigr)\\quad \\text{s.t.}\\ c\\le \\text{算力余量},\\ \\text{KV}(c)\\le \\text{预算}$$</div>\n<p>这个式子的工程含义是：chunk 太小，预填被切得过碎，每次迭代的固定开销（调度、kernel launch、TMEM 分配）摊薄不掉，预填总吞吐下降；chunk 太大，解码序列的 ITL 尾延迟被拉高。两者都是尾延迟来源，但方向相反，所以最优点在两条 p99 曲线的交点附近。对 Blackwell 上的实现，chunk 大小还受 tcgen05 MMA 的 tile 粒度约束——chunk 对应的 token 数若不能整齐映射到 MMA 的 N 维，会引入填充浪费，这部分算力代价在调度层不可见，只能通过算子层反馈回调度器。</p>\n<p>具体例子：一个批内 12 条序列在解码、1 条 8000 token 的请求待预填。若整段预填，12 条解码序列在这一迭代内全部停摆，ITL 出现一个等于整段预填时间的尖峰；若切成 8 个 1000 token 的 chunk，每个 chunk 与解码混批，解码序列每迭代仍能出一个 token，代价是长请求的 TTFT 被拉长到 8 个迭代。调度器在此处的判断是：解码侧已有 12 条序列在等 token，尾延迟的边际成本高于长请求首 token 的边际成本，于是选择切碎。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-29\">二十九 · 优先级与抢占：长尾样本单独成组与回压</h3>\n<p>论文对长尾样本的处理是单独分组并降低并发，而不是提高其优先级。这个方向值得注意：长尾样本在 rollout 侧是拖慢整批的元凶，但在调度语义上它并不是“更急”，而是“更贵”——它占用 KV 时间长、预填量大、解码步数多，若与短样本混批，会把整批的完成时间拉到它的水平。单独成组的意义是把长尾的代价隔离在一个小批内，让短样本批快速周转。降低并发则是控制长尾组对 KV 预算的占用速率，避免它把缓存吃到触发全局回压。</p>\n<p>抢占机制在这里的形态是回压而非驱逐：调度器监测 KV 占用，接近预算时回压 rollout 侧并发，即拒绝新请求进入组批队列，而不是把已在执行的序列踢出。这个选择的代价是 rollout 侧的样本生成被延迟，off-policy 陈旧度上升；收益是已在执行的序列不被中断，避免重算预填。驱逐式抢占在 KV 紧张时看似能腾出空间，但被驱逐序列的 KV 块释放后，重新调度时要重做预填，这部分算力代价往往高于等待。论文未给出回压触发阈值与恢复策略，这是其失败模式未描述的部分——阈值设得高，KV 频繁触顶，回压抖动；设得低，缓存利用率不足，吞吐下降。</p>\n<p>具体例子：长尾组内有 4 条序列，每条解码到 3000 token 以上，KV 占用接近预算的八成。此时短样本批的新请求到达，调度器不回压短样本，而是限制长尾组不再接纳新序列，并把长尾组的解码步与短样本批交错执行。结果是短样本批的周转不受长尾影响，长尾组的完成时间被拉长但不再恶化整批尾延迟。这里的取舍是明确的：牺牲长尾样本的完成时间，换整批的尾延迟分布收窄。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-30\">三十 · 分离式预填/解码在统一调度入口下的形态</h3>\n<p>论文把奖励模型与验证器推理作为独立请求流接入同一调度入口，这在结构上接近分离式预填/解码的雏形：rollout 的批量生成是预填密集、解码长尾的流，验证器推理是短预填、短解码的流，两者对算力和 KV 的需求形态不同。若分开调度，验证器侧的空闲算力无法被 rollout 的预填利用，rollout 侧的 KV 峰值也无法被验证器侧的低占用平抑。统一入口的价值在于让两类流在同一批内互补：验证器的短请求填充 rollout 长预填留下的算力碎片，rollout 的长解码填充验证器短请求之间的调度间隙。</p>\n<p>代价是调度复杂度上升：两类流的 SLO 不同，验证器侧要求低 TTFT，rollout 侧要求批次尽快完成以降低陈旧度，统一入口必须同时满足两个目标函数。式中的调度目标写成吞吐与尾延迟之比，但两个流的尾延迟定义不同——验证器看 TTFT p99，rollout 看整批完成时间的 p99。调度器若用单一尾延迟指标，必然偏向一侧。论文未给出两类流的请求比例与各自 SLO，因此这个偏置的实际幅度不可核验，只能确认机制上存在这一取舍。</p>\n<p>具体例子：一个迭代内 rollout 侧有 6 条长序列在解码，验证器侧到达 20 条短请求。若验证器请求单独排队，它们要等 rollout 批的整个解码周期结束；若混批，验证器请求的预填 chunk 插入 rollout 解码步之间，TTFT 从整批周期缩短到单迭代周期。代价是 rollout 解码步被预填 chunk 挤占，ITL 略微上升。调度器在此处选择混批，因为验证器侧的 TTFT 是硬 SLO，而 rollout 侧的 ITL 上升可被长尾组的独立分组吸收。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-31\">三十一 · 尾延迟的压缩路径：从批内方差到队列深度</h3>\n<p>尾延迟在批调度里有三个来源：批内序列完成时间的方差、组批等待、KV 回压抖动。Slim Scheduler 对第一个来源的处理是分组隔离——把方差大的长尾样本移出主批，主批的完成时间分布收窄。对第二个来源，组批等待与簇合并的收益直接冲突：合并越多，等待越长。对第三个来源，回压阈值决定抖动幅度。三条路径的取舍不是独立的：分组隔离降低了主批方差，但长尾组自身成为新的尾延迟来源；簇合并降低了预填算力，但拉长了 TTFT 尾部；回压平抑了 KV 峰值，但引入了并发抖动。</p>\n<p>工程判断上，尾延迟的压缩应优先作用于方差而非均值。批内方差大的时候，均值优化（提高批大小、提高并发）反而拉长尾部，因为长尾样本被更多短样本裹挟着等。分组隔离是把方差从主批剥离，代价是总算力利用率下降——长尾组并发低，算力碎片多。这个代价在 Blackwell 档位上体现为 SM 占用率下降与 TMEM 分配碎片化，调度层看不到，但会反映在吞吐上。论文未给出长尾判定阈值与队列长度上限，因此隔离的粒度无法量化，只能确认机制方向：先隔离，再回压，最后才考虑驱逐。</p>\n<p>具体例子：主批 32 条短序列，完成时间集中在 3 到 5 个迭代；长尾组 3 条序列，完成时间 40 个迭代以上。若不隔离，主批的 p99 被拉到 40 个迭代；隔离后主批 p99 回到 5 个迭代，长尾组 p99 仍是 40 但只影响 3 条样本。整批的尾延迟指标若按样本数加权，改善显著；若按批完成时间计，整批仍要等长尾组，改善为零。调度器必须明确尾延迟的统计口径，否则隔离的收益在指标上不可见。这是论文未展开但工程上必须回答的问题。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-32\">三十二 · 时延与吞吐的取舍落在哪个旋钮上</h3>\n<p>把上述机制收拢，Slim Scheduler 的时延-吞吐取舍实际落在三个旋钮上：组批的簇合并阈值、chunk 大小、回压触发点。簇合并阈值调高，预填复用率上升、吞吐上升、TTFT 尾部拉长；chunk 调小，ITL 尾部收窄、预填固定开销占比上升、吞吐下降；回压触发点调低，KV 峰值平抑、并发抖动增加、rollout 陈旧度上升。三个旋钮都不是独立的，簇合并让批内序列更长，chunk 要相应缩小以保护 ITL，回压触发点又要相应调高以容纳更长的 KV 占用。调参的联合空间是三维的，论文未给出任何一维的数值，因此这套旋钮在 Blackwell 上的实际工作点无法复现。</p>\n<p>可确认的工程判断是：运行时感知的价值不在于某个固定阈值，而在于调度器能读到批构成与 KV 占用这两个量，从而在每次组批时重新定位工作点。固定阈值的调度器在负载形态变化时会失配——短请求为主时簇合并阈值应低，长尾为主时隔离阈值应低，两种形态在同一服务里交替出现时，固定阈值必然在一侧失效。Slim Scheduler 把这两个量作为输入，至少让失配可被感知，但材料未给出感知之后的决策规则细节，这是其机制方向与可部署系统之间的缺口。对 Blackwell 部署而言，这个缺口的具体形态是：tcgen05 MMA 的 tile 粒度与 KV 分页粒度共同约束了 chunk 与簇的可选值集合，调度器若不知道这些约束，运行时感知读到的量无法映射到可执行的组批决策。</p>\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-33\">三十三 · 切分维度与通信原语的对应关系</h3>\n<p>在 Blackwell 上谈并行，第一步不是选 TP 还是 PP，而是先确认每种切分把哪一类通信放到了关键路径上。张量并行（TP）在每层内部切分权重矩阵，前向需要两次 All-Reduce（注意力输出投影后与 MLP 下投影后），反向亦然；流水并行（PP）只在阶段边界传激活，通信量随 micro-batch 大小线性增长但频次低；专家并行（EP）把 MoE 的专家分散到不同 rank，每层触发 All-to-All 做 token 路由与回收；数据并行（DP）在梯度侧做 All-Reduce 或 Reduce-Scatter，推理服务里则更多表现为请求级复制而非集合通信。对 CNN 推理服务而言，TP 与 EP 是延迟敏感项，PP 是吞吐项，DP 是容量项。Slim Scheduler 的材料明确未给出并行拓扑，因此这里只能给出判据：一旦调度器把长尾样本单独成组并降并发，它实际上是在缩小单个 TP 组的有效 batch，使 All-Reduce 的固定开销占比上升——这正是并行维度与调度策略耦合的地方。</p>\n<p>通信代价可用一个粗糙但够用的下界刻画。设单次集合通信传输量为 \\(S\\) 字节、链路有效带宽为 \\(B\\)、固定启动开销为 \\(\\alpha\\)，则单次耗时近似为</p>\n<div class=\"formula\">$$T_{\\text{coll}} \\approx \\alpha + \\frac{S}{B}\\cdot\\frac{2(N-1)}{N}$$</div>\n<p>其中 \\(N\\) 为参与 rank 数，因子 \\(2(N-1)/N\\) 来自 ring All-Reduce 的两阶段（Reduce-Scatter 与 All-Gather）。在 NVLink 5 与 NVSwitch 构成的单域内，\\(\\alpha\\) 被压得很低，\\(B\\) 足够大，于是小消息的集合通信几乎被启动开销主导；跨域走 InfiniBand 时 \\(B\\) 骤降，同一公式的第二项立刻成为主项。工程判断由此而来：TP 组必须留在 NVLink 域内，EP 的 All-to-All 若跨域则必须做 token 上限截断，否则单层延迟就被通信吃掉。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-34\">三十四 · NVLink 5、NVSwitch 与域边界</h3>\n<p>Blackwell 世代的 NVL72 机柜把 72 个 GPU 放进同一个 NVLink 域，NVSwitch 提供全互联而非仅邻居互联，这意味着 All-to-All 在域内的拓扑惩罚远小于此前的环状或胖树跨节点方案。对 EP 而言这是决定性优势：MoE 层每 token 要被路由到若干专家，All-to-All 的参与者数量直接决定消息碎片数，NVSwitch 的全互联把碎片化的路由消息压在同一跳数内完成。代价在功耗与散热侧：全互联交换芯片与铜缆背板使整柜功耗抬升，机柜级功率封顶成为容量规划的真实约束，而不是纸面带宽。推理系统里这表现为：能开多大的 EP 组，取决于机柜功率预算与单卡功耗，而非仅取决于显存。</p>\n<p>域边界同时是故障域边界。NVLink 域内的集合通信失败会拖垮整个 TP/EP 组，跨域链路抖动则表现为 PP 阶段边界的激活传输延迟尖峰。Slim Scheduler 把奖励模型与验证器推理作为独立请求流接入同一调度入口，若这些请求与 rollout 共享同一 TP 组，则验证器的小 batch 请求会拉低 TP 组有效 batch，使 All-Reduce 的固定开销摊薄变差；若它们被放到独立 DP 副本上，则跨副本的前缀共享与 KV 复用又需要走 NIXL 之类的传输层。材料未给出该系统的拓扑选择，因此这里只能标记为设计缺口：调度器读取 KV 占用却不读取通信域占用，就无法判断一次分组是否会把请求塞进一个正在被集合通信占满的 TP 组。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-35\">三十五 · All-to-All 与 All-Reduce 的瓶颈判据</h3>\n<p>两类原语的瓶颈条件不同。All-Reduce 的耗时对消息大小近似线性、对 rank 数近似对数（在 NVSwitch 全互联下），因此它在大 batch、大隐藏维度时是带宽项，在小 batch 时是启动开销项。All-to-All 则对消息碎片数敏感：EP 组越大，每 rank 要发给其他 rank 的子消息越多，有效带宽被小消息稀释。设每 token 路由到 \\(k\\) 个专家、序列长度 \\(L\\)、隐藏维度 \\(d\\)、精度字节数 \\(b\\)，则单层 All-to-All 的总字节量约为 \\(2kLdb\\)（发出与回收各一次），碎片数为 \\(N\\) 段。当 \\(L\\) 因长尾分组而变小时，碎片数不变而每段变小，带宽利用率下降——这就是 EP 在低并发下的固有劣势。</p>\n<table class=\"mini\"><thead><tr><th>原语</th><th>主导项</th><th>低 batch 时</th><th>高 batch 时</th><th>推理侧代价</th></tr></thead><tbody><tr><td>TP All-Reduce</td><td>启动开销 \\(\\alpha\\)</td><td>延迟被固定开销吃掉</td><td>转为带宽受限</td><td>单 token 延迟抬升</td></tr><tr><td>EP All-to-All</td><td>碎片数与带宽</td><td>带宽利用率低</td><td>路由不均衡放大</td><td>尾延迟抖动</td></tr><tr><td>PP 激活传输</td><td>micro-batch 大小</td><td>气泡占比高</td><td>接近带宽上限</td><td>吞吐而非延迟</td></tr><tr><td>DP 梯度/请求复制</td><td>副本数</td><td>无集合通信</td><td>请求分摊</td><td>显存复制成本</td></tr></tbody></table>\n<p>判据可以写成一句话：当单次集合通信耗时 \\(T_{\\text{coll}}\\) 超过该层计算耗时 \\(T_{\\text{compute}}\\) 的某个比例时，通信成为瓶颈。对 TP，这个比例在 decode 阶段极易被突破，因为 decode 每步只处理一个 token，计算量极小而复用同一组权重，All-Reduce 的固定开销无法被摊薄。这正是分离式预填/解码要把 decode 放在更大 TP 组或改用更少通信的并行方式的动因，具体切分策略属于其他片段的主题，此处只指出判据本身。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-36\">三十六 · NIXL 传输与跨阶段数据搬运</h3>\n<p>NIXL 解决的是集合通信之外的一类搬运：KV cache 块、前缀缓存、权重分片在节点间或存储与显存间的点对点传输。它把传输抽象成可被调度器查询的异步描述符，使预填节点与解码节点之间的 KV 交接不必走完整的集合通信路径。对 Slim Scheduler 这类把 rollout、奖励模型、验证器放进同一调度入口的系统，NIXL 的意义在于：前缀共享若跨进程或跨节点生效，复用命中与否取决于传输层能否在调度决策的时间窗内完成搬运。若调度器在分组时假定前缀可复用，而 NIXL 传输的实际完成时间超出该组的首 token 预算，则复用反而变成负收益——请求在等待 KV 到位时占着调度槽位。</p>\n<p>代价侧要盯三件事：传输带宽占用与集合通信争抢同一物理链路；传输完成事件与调度队列的耦合深度（同步等待会阻塞调度循环）；以及 KV 块粒度与传输描述符数量的关系，块越小描述符越多，调度器查询开销越大。材料未给出 KV 预算、淘汰策略与分页机制，因此无法量化前缀共享的实际命中率，只能定性判断：跨阶段复用能否生效，取决于调度器是否把传输完成时间纳入分组代价，而不是仅看 KV 占用百分比。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-37\">三十七 · 通信何时成为瓶颈：三个可观测信号</h3>\n<p>第一个信号是单步延迟中通信占比。在 decode 阶段采集每层 All-Reduce 耗时与计算耗时之比，若该比值随 batch 减小而单调上升，说明调度器的长尾分组正在把请求推进通信受限区。第二个信号是 EP 路由不均衡度：各 rank 收到的 token 数方差除以均值，方差抬升意味着 All-to-All 的某些段成为长尾，尾延迟由最慢 rank 决定。第三个信号是跨域流量占比：当 PP 阶段边界或 NIXL 搬运的字节量超过域内集合通信字节量时，跨域链路成为全局瓶颈，此时增加 TP 组规模只会加剧跨域压力。</p>\n<p>把这三个信号接进调度决策，就是运行时感知的实质。伪代码层面可写成：调度器在分组前读取每个候选组的通信占比估计与 KV 占用，若某组长尾样本占比高且其 TP 组通信占比已超阈值，则将该组降并发或迁移到通信负载较低的副本；若前缀可复用但 NIXL 传输预计完成时间超出首 token 预算，则放弃复用、走本地预填。这与材料中“调度器依据批内序列长度与 KV 缓存占用决定分组与复用”的描述同构，只是把通信状态补进了读取集合——材料本身未给出这一读取项，属于明确的工程缺口。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-38\">三十八 · 与调度目标的耦合</h3>\n<p>材料给出的调度目标是吞吐与尾延迟之比在 KV 预算约束下的最大化。把通信项写进该目标，可得到更贴近硬件的形式：</p>\n<div class=\"formula\">$$\\max_{\\pi}\\ \\mathbb{E}\\left[\\frac{\\text{吞吐}}{\\text{尾延迟}}\\right]\\ \\text{s.t.}\\ \\text{KV占用}\\le \\text{预算},\\ \\sum_{g}\\mathbb{1}[T_{\\text{coll}}(g)&gt;T_{\\text{compute}}(g)]\\le \\text{阈值}$$</div>\n<p>第二个约束的含义是：不允许过多分组落入通信受限区。工程上它对应一个可调参数——通信受限组的数量上限，超过则回压 rollout 并发或合并分组。这与材料中“KV 占用接近预算时回压 rollout 并发”是同一类机制，只是触发量从显存换成了通信。对 Blackwell 部署而言，这个约束的实际意义在于：NVL72 域内带宽充裕但功耗封顶，跨域链路带宽有限，调度器若只感知 KV 而不感知通信域占用，就会在域内把 TP 组塞满小 batch 请求，在域外把 PP 边界推到跨域链路上，两种情形都表现为尾延迟不可控。因此并行拓扑的选型与调度策略必须同源设计，而不是先定拓扑再套调度器。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-39\">三十九 · 并行切分与通信瓶颈：这套调度逻辑在哪里失效</h3>\n<p>Slim Scheduler 的调度入口只读取批构成、KV 占用与长度分布，材料中没有给出任何并行拓扑信息——TP/EP/PP/DP 的切分方式、NVLink 域大小、是否走分离式预填/解码均未说明。这直接决定了它的边界：运行时感知分组在单卡或单副本内是纯调度问题，代价只是队列与 KV 预算；一旦模型被切开，分组决策就变成通信决策。以 TP 为例，一次前向的每层需两次 All-Reduce，单 token 通信量近似 <span class=\"formula\">$$V_{\\text{comm}} \\approx 2\\,(N_{\\text{layer}})\\,b\\,h\\,\\frac{T-1}{T}$$</span>（b 为批内 token 数、h 为隐藏维、T 为 TP 度），当分组把长尾样本单独成组、批内 token 数 b 骤降时，All-Reduce 的固定延迟占比上升，算术强度被摊薄——这正是“降低并发保尾延迟”在 TP 拓扑下反噬吞吐的机制。EP 场景更尖锐：MoE 的 All-to-All 随专家并行度线性放大，调度器把验证器请求与 rollout 混排进同一入口，会让 All-to-All 的 token 路由在两种负载间抖动，NIXL 传输若跨节点则引入额外跳数。</p>\n<p>通信何时成为瓶颈，可用一个判据表达：设单组计算时间为 <span class=\"formula\">$$t_{\\text{comp}}$$</span>、通信时间为 <span class=\"formula\">$$t_{\\text{comm}}$$</span>，则分组收益仅在 <span class=\"formula\">$$t_{\\text{comm}}/t_{\\text{comp}} &lt; \\rho$$</span>（ρ 为可接受的通信占比）时成立；长尾单独分组恰恰把 t_comp 压小而不改变 t_comm，比值恶化。下表给出四种切分下调度决策的代价落点：</p>\n<table class=\"mini\"><thead><tr><th>切分</th><th>主要通信</th><th>调度代价落点</th><th>失效条件</th></tr></thead><tbody><tr><td>TP</td><td>每层 All-Reduce</td><td>小批时固定延迟占比升高</td><td>长尾组 token 数低于阈值</td></tr><tr><td>EP</td><td>All-to-All</td><td>混排导致路由抖动</td><td>验证器请求比例上升</td></tr><tr><td>PP</td><td>激活传递</td><td>流水气泡随分组变长</td><td>组内长度方差大</td></tr><tr><td>DP</td><td>梯度/权重同步</td><td>副本间负载不均</td><td>回压只作用于单副本</td></tr></tbody></table>\n<p>具体例子：调度器读到 KV 占用接近预算，回压 rollout 并发，长尾样本进入单独队列。若该副本为 TP=8、NVLink 5 域内互联，单组 token 数从数百降到数十，All-Reduce 的启动延迟不再被计算掩盖，单步时间由计算主导转为通信主导；此时“尾延迟改善”只在队列等待维度成立，端到端 token 时延反而被通信拉长。材料未给出回压触发阈值与恢复策略，也未给出 NVFP4 量化位置，因此无法判断量化后 All-Reduce 的数值路径是否改变分组收益。工程判断是：这套运行时感知调度在 DP 或单副本内可落地，跨 TP/EP 域时必须把通信拓扑作为调度状态的一等输入，否则分组越细、通信占比越高，调度目标中的吞吐/尾延迟比会反向退化。</p>\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-40\">四十 · 精度塌陷：从数值漂移到奖励信号失真</h3>\n<p>在 Slim Scheduler 这类把 rollout 与验证器推理塞进同一调度入口的系统里，精度塌陷不是单一算子的问题，而是调度决策与数值路径耦合后的连锁反应。材料明确未给出量化方案与硬件档位，因此无法核验 NVFP4 下的采样稳定性；这恰恰是诊断的起点：当调度器按批内长度分布分组、把可共享前缀的样本合并以复用 KV 时，同一批内不同样本可能走过不同的预填路径与不同的缓存命中状态，若某条路径上启用了低精度累加或压缩 KV，采样分布的尾部会被系统性削平。表现是奖励模型打分方差收窄、验证器通过率在长尾样本上突然掉档，而短序列组的指标仍然正常——这种“分组相关”的精度分化是定位的第一信号。</p>\n<p>机制上，调度器读取 KV 占用与长度分布做分组，等价于对样本施加了一个非随机的选择偏置。设组 $g$ 的样本集合为 $S_g$，其数值误差可写成组内前缀复用长度 $L_g$ 与精度路径 $q_g$ 的函数：</p>\n<div class=\"formula\">$$\\epsilon_g=\\sum_{i\\in S_g}\\left|\\hat{p}_i-p_i\\right|\\approx c\\cdot L_g\\cdot \\delta(q_g)$$</div>\n<p>其中 $\\delta(q_g)$ 是该路径的单位长度数值偏差。工程代价直接落在奖励信号上：rollout 侧追求长尾样本尽快完成以降低 off-policy 陈旧度，一旦长尾组被单独降并发、走更保守的精度路径，其奖励分布与短序列组不再可比，优势估计被组间偏差污染。具体例子：一个批次里前缀共享命中率高的短样本组用压缩 KV 快速出结果，长尾组因缓存未命中走全精度重算，两组在同一奖励模型下打分，验证器对长尾组的通过率出现台阶式下降——此时应冻结分组策略、把两组拆到独立调度队列并分别记录精度路径标签，而不是调奖励模型阈值。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-41\">四十一 · OOM 与 KV 预算：回压触发点才是真故障点</h3>\n<p>材料只确认调度器在 KV 占用接近预算时回压 rollout 并发，未给出预算数值、淘汰策略与回压阈值。这意味着 OOM 在工程上几乎从不以“显存分配失败”的形式第一次出现，而是以回压抖动、批构成突变、前缀命中率骤降的形式先出现。诊断要把 KV 占用拆成三块可观测的量：已分配页、可复用前缀页、以及因分组切换而暂时不可回收的“悬挂页”。悬挂页是这套联合调度特有的代价——当调度器把长尾样本从主组剥离时，原组已预填的前缀若无人再引用，页表项要等引用计数归零才释放，而回压恰好发生在引用计数尚未归零的窗口内。</p>\n<p>定位手法是给每次分组决策打上“预算快照”标签：记录决策时刻的占用 $U_t$、预算 $B$、以及该组预计新增页数 $\\Delta_g$，满足 $U_t+\\Delta_g&gt;B$ 即触发回压。伪代码思路是：</p>\n<ul>\n<li>读 $U_t$ 与批内长度分布，按前缀可复用长度降序贪心分组；</li>\n<li>对每组估算 $\\Delta_g$，若超预算则将该组降级为“延后队列”，不立即回压全局并发；</li>\n<li>仅当延后队列长度超过上限或 $U_t&gt;0.9B$ 时才回压 rollout 侧并发。</li>\n</ul>\n<p>代价是显存与吞吐的兑换：全局回压会让 rollout 批量生成的批大小收缩，off-policy 陈旧度上升；而只延后单组则把尾延迟转移到延后队列上。具体例子：一个长尾样本组因前缀未命中需要全量预填，$\\Delta_g$ 估算超过剩余预算，若直接全局回压，短序列组的在途请求被迫排队，整体吞吐掉档；正确做法是把该组挂起、让短组继续复用前缀跑完，等悬挂页回收后再放行长尾组。监控指标应盯“悬挂页占比”与“延后队列深度”，而非只看总占用率。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-42\">四十二 · 批抖动：分组策略在负载拐点处的振荡</h3>\n<p>批抖动是运行时感知调度最隐蔽的失败模式。调度器依据批内长度分布决定分组，而分组结果又反过来改变下一时刻的长度分布——短样本被合并快速消化，长尾被剥离，下一批到达时长度分布已经偏移，调度器再次改变分组阈值，形成周期性的批构成振荡。材料未给出长尾判定阈值与队列长度上限，因此这种振荡在缺少迟滞机制时必然出现。表现是批大小序列出现规律性起伏、前缀命中率锯齿状波动、以及验证器请求流的排队长度同步震荡。</p>\n<p>诊断的关键是给分组决策加“迟滞带”：设长度分位阈值为 $\\theta$，仅当批内长度分布的 $p_{90}$ 越过 $\\theta(1\\pm h)$ 时才切换分组模式，$h$ 为迟滞系数。代价是切换延迟：迟滞带越宽，批构成越稳定，但对真实负载变化的响应越慢，长尾样本可能在旧分组下多等一个调度周期。具体例子：在线服务侧请求长度分布因上游 prompt 模板变更整体右移，若无迟滞，调度器在每个调度周期都把边界样本在长短组之间来回搬，KV 前缀反复失效，预填算力被重复消耗；加迟滞带后，边界样本稳定留在长组，代价是这部分样本的尾延迟上升一个调度周期，但前缀命中率恢复稳定。监控应记录“分组切换频率”与“前缀命中率方差”，二者同时抬升即为批抖动。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-43\">四十三 · 尾延迟：长尾组隔离后的排队放大</h3>\n<p>材料确认长尾样本被单独分组并降低并发，但未给出长尾判定阈值、队列上限与尾延迟 SLO。把长尾剥离出主组能保护主组吞吐，代价是长尾组自身变成一个低并发、高排队的通道，其尾延迟由“队列深度 × 单样本生成时间”决定，而单样本生成时间又受前缀是否命中影响。诊断要把尾延迟分解为排队延迟与服务延迟两部分，分别对应调度器侧与引擎侧。设长尾组并发为 $c$、到达率为 $\\lambda$、单样本服务时间为 $s$，则队列等待近似为：</p>\n<div class=\"formula\">$$W_q\\approx\\frac{\\rho}{c(1-\\rho)}\\cdot s,\\quad \\rho=\\frac{\\lambda s}{c}$$</div>\n<p>当 $\\rho$ 接近 1 时尾延迟对并发 $c$ 极度敏感，而 $c$ 又被回压策略压低，形成正反馈。工程代价是 SLO 达成率：主组吞吐好看，长尾组 SLO 却持续违约，而端到端指标被主组样本稀释后看不出问题。具体例子：验证器推理作为独立请求流接入同一调度入口，其请求比例未给出，若验证器请求与长尾 rollout 样本共享低并发通道，验证器排队会反过来拖慢奖励回传，进一步拉长 off-policy 陈旧度。定位手段是给每个请求打“组标签 + 入队时间 + 首次预填时间”，分别统计主组与长尾组的 $p_{99}$，一旦长尾组 $p_{99}$ 与主组差距超过设定倍数，就应临时提升长尾组并发或放宽长尾判定阈值，而不是全局调大并发。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-44\">四十四 · 静默降级：没有告警的吞吐换精度</h3>\n<p>静默降级指系统在压力下自动走了更便宜的路径——跳过前缀复用、退回较短上下文、降低验证器采样次数——而指标面板上吞吐与成功率仍然正常。Slim Scheduler 的联合调度结构天然容易产生这类降级：调度器在 KV 占用接近预算时回压并发，rollout 引擎为维持产出可能缩短生成长度或减少验证器调用，而这些行为若不打标就无法与正常路径区分。材料未给出监控指标与告警阈值，因此静默降级只能靠“路径标签”而非“结果指标”来发现。</p>\n<p>机制上，给每条请求记录三个布尔位：是否命中前缀复用、是否走全精度路径、验证器是否完整执行。正常路径的三位全真；任一位置假即为降级。诊断规则是统计降级请求占比 $r_d$ 与其奖励分布偏移 $\\Delta\\mu$，当 $r_d$ 上升而端到端吞吐不变时，说明系统在用降级换吞吐。代价是奖励信号的可比性：降级样本与正常样本混在同一优势估计里，策略更新会被系统性拉偏。具体例子：KV 占用逼近预算，调度器回压 rollout 并发，引擎为保住批产出把部分样本的前缀复用关闭，这些样本的预填算力翻倍但生成结果仍被接受，面板上只看到吞吐持平、显存回落，实际是奖励分布已经偏移。回滚手段是给降级路径设硬上限：$r_d$ 超过阈值即冻结分组策略、恢复上一版调度参数，并把降级样本隔离出训练批次。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-45\">四十五 · 回滚与定位顺序：从指标到决策日志</h3>\n<p>这套系统的回滚不能只回滚模型权重，因为失败往往出在调度参数而非权重。定位顺序应是：先看分组切换频率与前缀命中率方差（批抖动），再看悬挂页占比与延后队列深度（OOM 前兆），再看长尾组与主组的 $p_{99}$ 差距（尾延迟），最后看降级请求占比与奖励分布偏移（静默降级）。精度塌陷通常排在最后确认，因为它表现为分组相关的指标分化，需要前几步的组标签才能归因。回滚粒度对应三层：调度参数层（分组阈值、迟滞带、回压触发点）可热切换；请求路径层（前缀复用开关、精度路径）需按组灰度；权重层最后动。</p>\n<p>工程判断落在决策日志的完整性上：每次分组决策必须记录输入（$U_t$、长度分布分位数）、输出（组划分、$\\Delta_g$ 估算）、以及触发的回压或延后动作。没有这份日志，上述五类失败模式都只能靠结果指标反推，而结果指标恰恰会被主组样本稀释。材料未给出权重同步频率与异步流水线深度，因此回滚时无法判断在途 rollout 样本属于哪个权重版本——这是这套联合调度在工程上最需要补的观测缺口：给每个样本打权重版本号与调度决策 ID，回滚时按决策 ID 批量作废在途样本，而不是等它们自然完成。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-46\">四十六 · 运行时回压的失效边界与可观测性缺口</h3>\n<p>这套联合调度最脆弱的环节是回压闭环本身。调度器只在KV占用接近预算时才对rollout侧限流，但材料未给出触发阈值、滞回区间与恢复策略，于是存在一个结构性风险：一旦长尾样本单独成组并降低并发，批内可复用前缀的样本比例随之下降，KV释放速度变慢，占用反而更容易顶到预算，形成“限流—复用率下降—占用更高—继续限流”的正反馈。用控制论的语言写出来就是：</p>\n<div class=\"formula\">$$u_{t+1}=u_t+\\alpha\\,(O_t-B)^{+}-\\beta\\,R_t,\\qquad \\frac{\\partial R}{\\partial u}&lt;0$$</div>\n<p>其中 $O_t$ 为KV占用、$B$ 为预算、$R_t$ 为前缀复用释放的缓存量。只要复用率对并发的敏感度高于占用对并发的敏感度，闭环就没有稳定不动点，表现为批抖动：批大小在相邻迭代间来回跳，rollout的off-policy陈旧度随之波动。诊断上应把“每批复用命中长度 / 批内总长度”与“KV占用斜率”作为一对联合指标采集，单看占用会误判为容量不足，单看命中率会误判为前缀分布变化。工程代价直接落在尾延迟上：抖动期间长尾组被反复重建，重复预填的算力开销按组内序列长度线性增长，而这段开销不产生任何新样本。</p>\n<p>精度塌陷与静默降级在本方案里几乎不可观测。材料明确未给出量化方案与硬件档位，因此无法核验NVFP4采样稳定性，也无法判断数值误差是否会改变调度决策所依赖的长度分布统计——采样温度漂移会改变生成长度，长度分布又反过来决定分组，误差因此进入调度回路而非停留在算子层。可落地的监控只能做差分式：对同一批前缀在复用与重算两条路径上分别取样，比较奖励模型打分的分布偏移；偏移超过设定带宽即判定为静默降级，触发回滚到关闭前缀复用的保守路径。代价是这条影子路径要额外占用一份KV与一份验证器算力，在验证器请求比例本就未给出的情况下，这部分开销无法从材料中估算，只能按“验证器吞吐被影子流量稀释”定性记录。</p>\n<p>OOM与尾延迟的定位需要区分两类根因：一类是长尾组队列无上限导致的显存单调爬升，另一类是验证器请求流与rollout争抢同一调度入口造成的排队倒挂。前者看“长尾组待处理token总量”的单调性即可判定，后者要看验证器请求的等待时间是否随rollout并发上升而上升——若是，则说明统一入口缺少按请求流类型的配额隔离，回滚手段应是给验证器流设独立并发上限而非整体降并发。下表给出可观测项与对应回滚动作的映射，均为机制层判断，不含任何实测阈值：</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首选观测量</th><th>回滚动作</th></tr></thead><tbody><tr><td>批抖动</td><td>复用命中长度占比与KV占用斜率</td><td>冻结分组，短序列固定合组</td></tr><tr><td>静默降级</td><td>复用/重算双路径打分偏移</td><td>关闭前缀复用</td></tr><tr><td>排队倒挂</td><td>验证器等待时间随rollout并发的变化</td><td>验证器流独立配额</td></tr></tbody></table>\n<p>边界判断落在一点上：该方案的调度收益依赖“运行时状态可读且可信”，而材料未给出权重同步频率与异步流水线深度，意味着调度器读到的KV占用与长度分布可能是跨权重版本的陈旧快照，据此做的分组决策在权重切换后立即失效。因此部署时应把权重版本号写入调度决策的输入签名，版本不匹配即拒绝复用、退回逐请求预填——这不是性能优化，而是把不可观测的精度风险转成可观测的吞吐损失。</p>\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-47\">四十七 · 口径缺失下的“可比性”判定</h3>\n<p>读这篇论文的基准部分，第一件要建立的判断不是“它比谁快多少”，而是“它到底有没有资格被放进同一张对比表”。材料给出的可核验事实极少：硬件档位未给出、并行拓扑未给出、量化方案未给出、批大小与并发上限未给出、数据集与基线未给出、吞吐与尾延迟数字未给出。这意味着任何跨系统的横向比较在方法学上都不成立——不是数字偏小的问题，而是分母（硬件、精度、负载）全部空缺，比值无从定义。</p>\n<p>工程上判断一组推理数字可比，至少要锁定五个维度：算力档位（SM100/SM103 的差异直接改变 tcgen05 与 TMEM 的可用预算）、数值精度（NVFP4 与 FP8 的吞吐与采样稳定性不同量级）、批构成（序列长度分布决定 KV 占用曲线）、并发与 SLO 阈值（尾延迟的定义随分位数漂移）、以及是否包含预填阶段。缺任一项，两个吞吐数字之间就隔着一条无法闭合的口径差。本文材料在这五项上全部标注“未给出”，因此其收益只能作为机制方向的证据，不能作为容量规划的输入。</p>\n<p>把这一点写成可执行的判定式：设系统 A 报告吞吐 $T_A$、系统 B 报告 $T_B$，只有当两者的硬件档位向量 $\\mathbf{h}$、精度向量 $\\mathbf{q}$、负载分布 $L$ 与 SLO 约束 $S$ 在容差内一致时，$T_A/T_B$ 才有意义。否则应退化为定性比较：谁在机制上减少了重复预填、谁在机制上隔离了长尾。</p>\n<div class=\"formula\">$$\\text{可比性}=\\mathbb{1}\\left[\\lVert \\mathbf{h}_A-\\mathbf{h}_B\\rVert\\le\\epsilon_h\\right]\\cdot\\mathbb{1}\\left[\\mathbf{q}_A=\\mathbf{q}_B\\right]\\cdot\\mathbb{1}\\left[D(L_A\\Vert L_B)\\le\\epsilon_L\\right]$$</div>\n<p>代价落在哪里：口径不明时，读者最容易犯的错是把“调度机制更精细”误读为“吞吐更高”。在 Blackwell 上，一次错误的容量估算会直接转化为显存超配或功耗墙触发，前者导致 KV 预算被挤爆、后者导致 SM 降频，两者都以尾延迟恶化的形式暴露，而不是以吞吐数字的形式暴露。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-48\">四十八 · 模型与硬件档位：未给出即不可外推</h3>\n<p>材料明确写“硬件档位、并行拓扑与量化方案均未给出”，并进一步限定“无法判断其在 Blackwell 部署下的适用性”。这句话的工程含义比字面更重：调度器的分组决策依赖 KV 占用与批内长度分布，而这两个量的绝对尺度由硬件决定。B200 与 GB200 NVL72 的单卡显存与 NVLink 5 域大小不同，同一套“占用接近预算即回压”的逻辑，在不同档位上触发的时刻完全不同。若论文未声明档位，则其回压阈值的物理含义无法还原。</p>\n<p>量化方案缺失同样致命。NVFP4 下 KV cache 的字节占用约为 FP8 的一半量级，前缀共享的收益随之改变——共享一段前缀省下的显存，在 FP4 下更少，在 FP8 下更多。调度器若以“KV 占用”为唯一信号而不区分精度，分组策略在不同精度下的最优解会漂移。材料未给出量化位置，故无法判断其分组逻辑在 NVFP4 采样场景下是否仍然自洽，也无法核验采样稳定性。</p>\n<p>具体例子：假设某部署在 B200 上以 FP8 跑 rollout，KV 预算按字节计；若把同一调度器平移到 NVFP4 部署，KV 占用信号整体缩小，回压阈值若按绝对字节硬编码，则会在远未触及真实预算时就回压并发，rollout 吞吐被人为压低，off-policy 陈旧度上升。这不是调度算法错，而是口径未随精度重标定。</p>\n<p>代价维度：硬件档位缺失使功耗与带宽预算无法核算。tcgen05 与 2-SM MMA 的吞吐上限、TMEM 的容量约束、HBM 带宽与 NVLink 5 的跨卡流量，都是容量规划的分母；分母缺失时，任何“提升”都只是分子上的局部观察。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-49\">四十九 · batch、并发与负载分布：分母藏在分布里</h3>\n<p>材料对批大小的表述是“未给出批量生成的批大小数值或token上限”，对并发是“未给出并发上限与尾延迟SLO阈值”，对请求长度分布是“未给出具体分布形态与分位数，仅提及长尾样本需单独分组”。这三项合起来构成推理基准的核心分母。吞吐的定义是单位时间完成的 token 数或请求数，而它随批大小非线性变化：小批时延迟主导、大批时显存与带宽主导，中间存在一个由 KV 占用曲线决定的拐点。不声明批大小，吞吐数字就落在一条未知曲线上。</p>\n<p>更关键的是长尾。调度器的卖点是对长尾样本单独分组并降低并发，但“长尾”的判定阈值未给出。尾延迟的改善幅度完全取决于长尾占比：若长尾样本占批的极小比例，单独分组带来的隔离收益有限，反而增加分组开销；若占比可观，隔离才真正降低整批的完成时间。材料未给占比，故改善幅度不可核验。</p>\n<p>伪代码层面的口径还原思路：给定长度分布 $L$ 与批上限 $B$，调度器把批划分为短组 $G_s$ 与长尾组 $G_l$，则整批完成时间近似为</p>\n<div class=\"formula\">$$T_{\\text{batch}}\\approx\\max\\left(\\tau(G_s),\\ \\tau(G_l)\\right)+\\tau_{\\text{group}}$$</div>\n<p>其中 $\\tau_{\\text{group}}$ 是分组与 KV 复用判定的开销。若 $G_l$ 被降低并发，$\\tau(G_l)$ 上升但不再拖慢 $G_s$；净收益取决于 $\\tau_{\\text{group}}$ 与长尾占比的乘积。材料未给这些量，公式只能作为分析框架而非复现依据。</p>\n<p>具体例子：一个 rollout 批里混有短样本与一条超长样本，若不分组，整批等待超长样本完成，短样本的 KV 被无谓占用，显存压力持续到批结束；分组后短组先释放 KV，长尾组独占少量并发。代价是分组判定本身要读长度分布，这一步在高并发下是额外的调度开销，材料未给出该开销的量级。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-50\">五十 · 指标语义：TTFT、TPOT、吞吐、显存、功耗各自的口径陷阱</h3>\n<p>材料未给出任何吞吐、尾延迟或 SLO 达成数字，因此本节的 task 不是复述数字，而是界定每个指标在本文语境下的可读边界。TTFT 在 RL rollout 场景中与在线服务语义不同：rollout 的“首 token”往往对应批量生成的起步，其延迟被批内其他序列的预填挤占；若不声明是否包含排队时间，TTFT 不可比。TPOT 同理，批量生成时单序列的 token 间隔受批内并发与 KV 复用命中率影响，材料未给命中率，TPOT 无法归因。</p>\n<p>吞吐必须区分三种口径：token 吞吐、请求吞吐、以及“有效吞吐”（扣除验证器与奖励模型推理后的净生成量）。本文把奖励模型与验证器推理作为独立请求流接入同一调度入口，材料未给出其请求比例与批大小，故验证器侧吞吐代价不明——这意味着报告的吞吐若只计 rollout 生成，就系统性高估了端到端有效吞吐。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>本文可读边界</th><th>缺失项导致的偏差方向</th></tr></thead><tbody><tr><td>TTFT</td><td>未声明是否含排队与预填</td><td>偏低估计，掩盖调度排队代价</td></tr><tr><td>TPOT</td><td>未给 KV 复用命中率</td><td>无法归因，批内干扰被平均掉</td></tr><tr><td>吞吐</td><td>未区分 rollout 与验证器</td><td>高估端到端有效吞吐</td></tr><tr><td>显存</td><td>未给 KV 预算与淘汰策略</td><td>无法判断回压触发点</td></tr><tr><td>功耗</td><td>未给硬件档位</td><td>无法核算功耗墙与降频风险</td></tr></tbody></table>\n<p>显存与功耗的口径陷阱在于它们是约束而非产出。调度器在 KV 占用接近预算时回压并发，材料未给回压触发阈值与恢复策略，故显存指标只能定性描述为“存在预算约束下的回压行为”，不能量化为“节省了多少显存”。功耗侧，档位缺失使任何能效比都失去分母。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-51\">五十一 · 哪些提升不可比：三类典型误读</h3>\n<p>第一类误读是把机制收益当作吞吐收益。本文的创新点是运行时感知分组与统一调度入口，材料只确认了设计意图，未给出消融实验设置与结果，因此无法判断运行时感知模块、KV 复用策略与分组调度各自的贡献。没有消融，就无法把“吞吐提升”拆解到具体机制上，任何归因都是猜测。</p>\n<p>第二类误读是跨精度外推。材料明确“无法判断 NVFP4 下采样稳定性与数值精度对调度决策的影响”。NVFP4 的采样稳定性与调度决策之间存在间接耦合：若采样需要更高精度回退，rollout 的有效吞吐下降，调度器的分组假设（长度分布稳定）被打破。未给量化方案时，把 FP8 下的机制结论平移到 NVFP4 部署，属于口径越界。</p>\n<p>第三类误读是把单侧吞吐当作端到端 SLO。材料指出 rollout 追求长尾尽快完成以降低 off-policy 陈旧度，服务侧追求吞吐与 SLO，两者目标不一致。若报告只给 rollout 侧吞吐，则完全遗漏了验证器推理的排队代价与权重同步的工程代价——材料未给权重同步频率与异步流水线深度，训练与推理解耦的代价无法评估。这三类误读的共同结构是：分子可见、分母缺失。</p>\n<p>具体例子：某读者看到“调度器对长尾单独分组”便推断尾延迟下降，但材料未给长尾判定阈值与队列长度上限，若长尾组并发被压得过低，长尾样本自身的完成时间反而拉长，整批尾延迟由长尾组决定而非短组，净效果可能反转。这不是反例，而是口径缺失下无法排除的可能性。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-52\">五十二 · 工程判断：把这篇论文放在什么位置</h3>\n<p>基于材料，正确的工程判断是：该工作应被定位为机制方向的参考，而非数据来源。它的可迁移价值在于三点——调度决策读取运行时 KV 占用与批构成、奖励模型与验证器推理接入同一调度入口、长尾样本单独分组并回压并发。这三点在 Blackwell 部署上都有对应的落地位置：KV 占用信号可对接分页 KV 管理，统一调度入口可对接分离式预填/解码的请求路由，回压逻辑可对接连续批处理的并发上限。</p>\n<p>但要把机制变成可核验的容量规划，必须先补齐口径：声明硬件档位与量化位置、给出批大小上限与并发上限、给出长度分布的分位数与长尾占比、给出验证器请求比例与 SLO 阈值、给出回压触发与恢复策略。缺这些，调度目标</p>\n<div class=\"formula\">$$\\text{调度目标}=\\arg\\max_{\\pi}\\ \\mathbb{E}\\left[\\frac{\\text{吞吐}}{\\text{尾延迟}}\\right]\\quad \\text{s.t.}\\ \\text{KV占用}\\le \\text{预算}$$</div>\n<p>就只是一个形式化的意图声明，无法求解，也无法与任何现有系统对比。工程上真正可执行的下一步不是复现其数字，而是把上述五个口径量在自己的部署上测出来，再用同一套运行时信号去校准分组阈值——这才是这篇论文在 Blackwell 推理栈中能站住的位置。</p>\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-53\">五十三 · 迁移的第一道坎：调度器读什么，决定它能搬多远</h3>\n<p>Slim Scheduler 的调度入口只依赖两类运行时信号：当前 KV 缓存占用与批内序列长度分布。这个输入集合很窄，窄到它既是可迁移性的来源，也是可迁移性的上限。窄的好处是接口清晰——任何能吐出“KV 占用标量 + 长度直方图”的推理栈都能接上这套逻辑；坏处是它把调度决策的信息基础锁死在两个维度上，凡是对这两个维度不敏感的负载形态，迁移过去就等于空转。</p>\n<p>把调度目标写成约束形式，能看清迁移时哪一项会失效：</p>\n<div class=\"formula\">$$\\text{调度目标}=\\arg\\max_{\\pi}\\ \\mathbb{E}\\left[\\frac{\\text{吞吐}}{\\text{尾延迟}}\\right]\\quad \\text{s.t.}\\ \\text{KV占用}\\le \\text{预算}$$</div>\n<p>这个目标函数隐含一个假设：尾延迟的主要来源是长尾样本对整批的拖拽，而 KV 占用是并发的主要约束。迁移到 CNN 推理服务时，第一个假设通常还成立（大分辨率图像的预处理与卷积链长尾确实拖批），第二个假设却经常不成立——CNN 推理的显存瓶颈往往在激活值与权重驻留，而不是 KV。此时调度器读到的“KV 占用”要么恒为零，要么是个与真实瓶颈无关的代理量，约束项形同虚设，调度退化为纯粹按长度分组。这就是判断迁移可行性的第一条准则：**先确认目标负载的瓶颈是否落在调度器所读的信号上**，否则搬过去只是搬了个分组器。</p>\n<p>具体例子：把该调度器接到一个以固定分辨率图像分类为主的服务上，请求长度分布近乎单点，KV 复用无从谈起，前缀共享也无对象，调度器唯一还能起作用的是长尾分组——但固定分辨率下长尾本就稀少，收益趋近于零。反过来，接到变分辨率检测或视频帧序列服务上，长度分布重新变得有信息量，调度逻辑才有落脚点。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-54\">五十四 · RL 侧耦合是硬约束：脱离 rollout 语义就失去一半机制</h3>\n<p>这套系统的一半价值来自它同时看见 rollout 批量生成与奖励模型/验证器推理两条请求流。迁移到纯在线服务时，验证器请求流不存在，调度器失去“优先或延后处理”的第二类对象，只剩单流分组。此时它退化成一个普通的长度感知批调度器——这类东西在 vLLM 的 continuous batching 与 TensorRT-LLM 的 in-flight batching 里已有成熟实现，迁移过来不构成增量。</p>\n<p>更麻烦的是 RL 侧耦合的代价在迁移时会被放大。原设计中调度器在 KV 占用接近预算时回压 rollout 并发，这个回压动作依赖 rollout 引擎愿意接受外部节流。迁到别的 RL 框架时，如果 rollout 引擎的并发由自身采样逻辑决定、不接受调度器回压，那么“KV 占用接近预算”这一分支就只能降级为被动排队，长尾样本的隔离也就失去执行力。伪代码层面，可迁移的最小契约是：</p>\n<ul>\n<li>调度器暴露一个 <em>admit(n)</em> 接口，rollout 引擎在发起每批生成前调用它，返回本批允许的并发上限；</li>\n<li>调度器暴露一个 <em>classify(request)</em> 接口，返回分组标签（可共享前缀 / 长尾 / 普通）；</li>\n<li>两条流共用同一个排队入口，否则前缀共享无法跨阶段生效。</li>\n</ul>\n<p>代价判断：满足这三条契约的框架，迁移工作量集中在适配层；不满足的框架，要么改 rollout 引擎的并发控制点（侵入式改动，风险高），要么放弃回压机制（收益打折）。这是工程判断而非口号——**能不能迁，取决于目标框架是否允许调度器成为并发的唯一裁决者**。</p>\n<p>具体例子：在一个把 rollout 并发写死在采样配置里的框架上接入该调度器，调度器只能做事后分组，KV 占用逼近预算时无法主动降并发，结果是长尾样本仍然挤在同一批里，尾延迟控制失效。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-55\">五十五 · 规模上限：分组粒度与状态读取频率决定天花板</h3>\n<p>调度器每次决策都要读一次运行时状态。批越大、请求越密，状态读取的相对开销越低，分组收益越明显；但当批规模超过某个点，分组本身变成瓶颈——把上千条请求按前缀可共享性聚类，聚类开销随请求数增长，而调度器材料中未给出分组算法的复杂度与分组上限。可迁移的规模上限因此由两个量共同决定：单次状态读取的延迟，与单批内可区分组的数量。</p>\n<p>定性地说，当批内长度分布接近单峰、前缀命中率低时，分组带来的吞吐增益被分组开销吃掉，调度器应当退化为不分组的 FIFO 加长度排序。这个退化阈值就是规模上限的工程表达：**调度器的有效规模区间是“长度分布有足够方差、且前缀可复用比例足够高”的那一段**，超出这段，收益递减甚至转负。材料未给出前缀共享比例与长尾占比阈值，因此无法给出具体拐点，只能给出判断方向。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>调度器有效性</th><th>迁移判断</th></tr></thead><tbody><tr><td>长度方差大、前缀命中高</td><td>分组与复用同时生效</td><td>值得迁移，需保证回压契约</td></tr><tr><td>长度方差大、前缀命中低</td><td>仅长尾分组生效</td><td>可迁移，收益限于尾延迟</td></tr><tr><td>长度方差小、前缀命中高</td><td>仅复用生效</td><td>可迁移，需确认 KV 预算真实约束</td></tr><tr><td>长度方差小、前缀命中低</td><td>退化</td><td>不迁移，用现成批调度器</td></tr></tbody></table>\n<p>具体例子：一个请求长度集中在单一档位、且系统提示词完全相同的客服问答服务，前缀命中率极高但长度方差极小，调度器的分组维度失效、复用维度有效——此时迁移的正确做法是只保留前缀共享路径，砍掉长尾分组逻辑，减少状态读取频率以降低调度开销。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-56\">五十六 · 不适用区：KV 不是瓶颈、或尾延迟不由批构成决定</h3>\n<p>明确划出三类不适用场景，比泛泛谈“适用范围广”更有工程价值。</p>\n<p>第一类，KV 缓存不是并发约束的负载。CNN 推理服务中，若显存主要被权重与激活占据、批大小受算力而非显存限制，调度器的 KV 约束项失效，回压机制失去触发依据。此时强行迁移会把算力瓶颈误判为显存瓶颈，导致并发被不必要地压低，吞吐下降。</p>\n<p>第二类，尾延迟由单请求内部阶段决定而非批构成决定。若长尾来自某个算子的固定开销（例如大核卷积的尾部效应）或数据预处理阻塞，把长尾样本单独分组只是把它们挪到另一个队列，单请求延迟不变，整批尾延迟也不变。调度器能治的是“长尾拖累同批其他请求”，治不了“长尾自身就慢”。</p>\n<p>第三类，请求流单一且无 RL 语义。前面已述，此时调度器退化为普通批调度器，迁移不构成增量，反而引入状态读取与分组开销。</p>\n<p>代价量化方向：在不适用区迁移，代价是可测的——调度开销（每次决策的状态读取与分组计算）叠加在原有路径上，而收益为零或负。判断准则因此是：**先测目标负载的尾延迟归因，若长尾不来自批内互相拖拽，则不迁移**。</p>\n<p>具体例子：一个视频帧序列推理服务，尾延迟主要来自解码阶段的固定启动开销，调度器把长帧单独分组后，长帧自身的启动开销不变，短帧批次反而因为分组损失了填充效率，整体吞吐下降。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-57\">五十七 · 迁到 Blackwell 栈时要补的三件事</h3>\n<p>材料明确未给出硬件档位、并行拓扑与量化方案，因此把该调度器迁到 B200/B300 或 GB200 NVL72 上时，有三件事必须由迁移者自己补齐，且每一件都影响调度决策的正确性。</p>\n<p>其一，KV 预算的物理含义要重算。在分离式预填/解码拓扑下，预填节点与解码节点的 KV 占用口径不同，调度器读到的单一标量无法区分两段压力。迁移时需把“KV 占用”拆成预填侧与解码侧两个读数，否则回压会压错对象——压了预填侧并发，解码侧仍然堆积。</p>\n<p>其二，NVFP4/FP8 量化改变采样稳定性，进而改变调度决策的可信度。材料未给出量化方案，无法核验 NVFP4 下的采样稳定性；迁移者若在量化后运行，需确认奖励模型与验证器的打分在低精度下是否漂移，因为调度器对长尾样本的优先/延后判断依赖验证器结果，打分漂移会让分组标签本身失真。这是数值精度与调度逻辑的耦合点，不能分开评估。</p>\n<p>其三，并行与通信拓扑决定状态读取的成本。在 NVLink 5 域内多卡张量并行下，读取全局 KV 占用需要跨卡聚合，聚合延迟随并行度上升；调度器若每批都读一次全局状态，聚合开销会进入关键路径。迁移时需把状态读取改为周期性采样或分层聚合，用状态新鲜度换调度开销——这是可接受的工程折衷，因为调度决策对状态的时间分辨率要求本就不高。</p>\n<p>具体例子：在 GB200 NVL72 的一个机架内跑张量并行推理，调度器若逐批聚合全机架 KV 占用，聚合本身成为尾延迟来源；改为按节点本地读数加周期性全局同步后，调度开销退出关键路径，分组逻辑仍能生效。</p>\n\n<h3 id=\"paper-slim-scheduler-a-runtime-aware-rl-an-2025-sec-58\">五十八 · 边界内的正确用法：把调度器当约束执行器而非优化器</h3>\n<p>迁移判断最终落在一个定位问题上：这套调度器的强项不是找到最优批构成，而是在给定运行时约束下执行分组与回压。把它当优化器用，会期待它提升吞吐；把它当约束执行器用，才能稳定拿到它真正能给的東西——长尾隔离与 KV 预算内的并发控制。</p>\n<p>工程上可操作的迁移路径是：先在目标栈上只接入回压契约（admit 接口），验证 KV 占用逼近预算时并发确实下降且尾延迟不恶化；再接入分组逻辑，用长度直方图与前缀命中率两个指标判断分组是否带来净收益；最后才接入跨流共享入口。每一步都可单独回退，避免一次性搬入全部机制后在不适用的负载上付出调度开销却拿不到收益。规模上限的判断也随之落地：当分组净收益转为负值时，停在第一步即可，回压契约本身仍有价值。</p>\n<p>具体例子：在一个 CNN 检测服务上按此路径迁移，第一步回压契约在显存逼近上限时把并发从高位压回，避免了 OOM 重试带来的尾延迟尖峰；第二步分组因长度方差不足而净收益为零，遂停用分组、保留回压。这就是边界内的正确用法——**调度器的可迁移内核是回压，分组是可选项**。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Slim Scheduler: A </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Runtime-Aware RL and …</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Slim Scheduler: A Runti… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出具体基线系统</td></tr><tr><td>主要结果</td><td>材料未给出可核验的吞吐、尾延迟或SLO达成数字，仅能确认论文以运行时感知调…</td></tr><tr><td>消融</td><td>材料未给出消融实验设置与结果，无法判断运行时感知模块、KV复用策略与分组调…</td></tr><tr><td>局限</td><td>材料未给出实验规模、硬件配置与失败模式分析；调度器对KV复用与前缀共享的实…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-slim-scheduler-a-runtime-aware-rl-an-2025 · 共 9 个片段</p>\n";break;}}})();
